export default {"identity":{"full_name":"Lakshya Chopkar","location":"Pune, Maharashtra","professional_title":"UX & Product Designer"},"currentProfile":{"professional_title":"UX & Product Designer","focus":"Interaction design and hands-on prototyping","availability":"Open to internships and full-time roles from January 2027, after my juries. Open to any location, remote or in office.","availability_month":"2027-01","work_types":["Internship","Full-time"],"location_preference":"Any location; remote or in office"},"summary":["Pursuing an M.Des in User Experience after studying Electronics and Telecommunication.","Designed websites and mobile apps in contract and internship roles.","Co-designed a physical-digital learning game."],"education":[{"institution":"MIT ADT University, Pune","qualification":"M.Des in User Experience","status":"Pursuing","dates":"Jul 2025 - Jul 2027 (expected)","grade":{"label":"CGPA","value":8.6,"scale":10,"status":"current"}},{"institution":"SSIPMT Raipur","qualification":"B.Tech in Electronics & Telecommunication","dates":"2019 - 2022","grade":{"label":"Percentage","value":72.72}}],"experience":[{"organization":"Baragaun","title":"Product Designer (Contract)","dates":"Nov 2023 - Jan 2024","responsibilities":["Designed layouts for a responsive website after competitor and secondary research; completed the design handoff for development.","Developed wireframes, mockups and an interactive prototype for a mobile app. Presented user flows in stakeholder reviews."]},{"organization":"Novae Avenue","title":"Product Design Intern","dates":"Jul 2023 - Aug 2023","responsibilities":["Designed a data portal, landing page and brochure for customers of a 4G dashcam product.","Redesigned the dashcam app's customer-facing core and secondary screens."]}],"tools":{"design_research":["Figma","ProtoPie","Illustrator","Photoshop","Miro","FigJam","Google Forms"],"ai":["ChatGPT","Figma Make","Claude","GitHub Copilot","Gemini","Midjourney","Perplexity","NotebookLM (Google)","Antigravity","Google Search (AI Mode)","LLM Arena"],"development":["CSS","HTML","Visual Studio Code","GitHub"],"source":{"page":2,"section":"Skills / Design & Research Tools; AI Tools; Development"},"project_specific":[{"project":"ConnectAid","items":["Figma","FigJam","Google Forms","Miro"],"source":{"page":1,"section":"Projects / ConnectAid / Tools & technologies"}},{"project":"20 cc Syringe","items":["Figma","3D printing"],"source":{"page":1,"section":"Projects / 20 cc Syringe / Tools & technologies"}},{"project":"Giggles","items":["Figma","Arduino C++","ESP32","RFID (MFRC522)"],"source":{"page":1,"section":"Projects / Giggles / Tools & technologies"}}]},"methods":{"ux_design":["Information Architecture","Interaction Design","User-Centered Design","User Interface Design","Design Systems","User Flows","Design Iteration","Data Portal Design"],"research_evaluation":["User Interviews","Contextual Inquiry","User Research","Survey Design","Research Synthesis","Competitive Analysis","Persona Creation","Journey Mapping","Heuristic Evaluation","Usability Testing","Eye-Tracking","NASA-TLX"],"design_outputs":["Wireframing","Prototyping","Interactive Prototypes","High-Fidelity Screens","Infographics","Illustrations","Animations","Design Handoff"],"collaboration_working_style":["Analytical Thinking","Problem-Solving","Cross-Functional Collaboration","Communication","Planning & Organising","Leadership","High-Pressure Resilience","Stakeholder Communication"],"source":{"page":2,"section":"Skills"}},"coursesAndWorkshops":[{"title":"UX Design Process","provider":"Google","platform":"Coursera"},{"title":"UI/UX Training","provider":"Internshala"},{"title":"UX Workshop","provider":"GrowthSchool"},{"title":"Graphic Design Elements for Non-Designers Specialization","provider":"University of Colorado Boulder","platform":"Coursera"},{"title":"Basic Elements of Design: Design Principles and Software Overview","provider":"University of Colorado Boulder","platform":"Coursera"},{"title":"Textual Elements of Design: Fonts, Typography, and Spacing","provider":"University of Colorado Boulder","platform":"Coursera"},{"title":"Print and Digital Elements of Design: Branding and User Experience","provider":"University of Colorado Boulder","platform":"Coursera"},{"title":"Graphic Elements of Design: Color Theory and Image Formats","provider":"University of Colorado Boulder","platform":"Coursera"},{"title":"Fundamentals of Graphic Design","provider":"California Institute of the Arts","platform":"Coursera"},{"title":"Introduction to Imagemaking","provider":"California Institute of the Arts","platform":"Coursera"},{"title":"Ideas from the History of Graphic Design","provider":"California Institute of the Arts","platform":"Coursera"}],"recognition":[{"claim":"Following the first review round, the syringe redesign was shortlisted for research-paper presentation at Humanizing Work and Work Environment 2026 (HWWE 2026), UPES School of Design (9-11 Dec 2026). Publication remains subject to jury review.","event":"Humanizing Work and Work Environment 2026","stage":"Shortlisted after first review round","publication_status":"Subject to jury review"},{"claim":"Giggles received the Best Project award at Meraki.","award":"Best Project","event":"Meraki"},{"claim":"The syringe project was presented and received positive jury feedback on the knowledge and the 3D-printed prototype."}],"contact":{"instructions":"Direct visitors to the Contact section for email, phone, LinkedIn and Behance, or to the resume link. The actual contact values are rendered by the website.","url":"#contact","resume":"/normal-portfolio/assets/Lakshya-Chopkar-UX-Designer-Resume.pdf"},"projects":[{"id":"pixel-mania","title":"Pixel Mania","contribution":"I designed the concept, visual system, original assets, screens, motion and Figma prototype. I co-created the browser exploration with AI-assisted coding and reviewed its behaviour against my design.","duration":"4 weeks","summary":"Pixel Mania is a drawing board for general visitors and casual creative play. Each click changes a square’s colour. There is no score or assigned image: players make a picture, a name or an activity of their own. I designed the visual system, assets and complete Figma prototype, then used AI-assisted coding to explore a browser version. Visitors tried it on an iPad at an exhibition.","overview":[],"sections":[{"title":"Design challenge","blocks":[{"type":"paragraph","text":"I wanted to make a drawing board that was easy to start but did not tell people what to draw. Games such as Mario and Contra inspired the starting point: build recognisable images from small squares, then let each square become a reusable part of the interface and interaction."},{"type":"paragraph","text":"I combined pixel art with neo-brutalism: flat colour, hard borders, blocky shapes and solid shadows offset from the controls. The square became more than decoration. It shaped both the drawing surface and the controls around it."},{"type":"paragraph","text":"I chose a board without a score, timer or assigned drawing. The square changing colour is the immediate response to an action; the player decides what counts as a finished result. That made the first-click explanation more important than instructions for a particular game."}]},{"title":"Sketches","blocks":[{"type":"paragraph","text":"I sketched the drawing board, its controls and the entry screen on paper. I kept the board as the main activity and explored where the title, name field, start button and illustrations should sit around it."},{"type":"paragraph","text":"I then carried the layout into Figma and built shared components. That let me reuse the same controls and states across the screens."}]},{"title":"Interaction","blocks":[{"type":"paragraph","text":"In the browser exploration, 28 columns and 18 rows create a 504-cell board. Each click advances a cell through cream, blue, orange, lime and magenta, then back to cream. The colour chips above the board explain the sequence."},{"type":"paragraph","text":"I kept colour selection inside the cell, so the same action chooses a colour and paints the square. There is no separate colour-picker step to learn. The trade-off is repeated clicking: reaching a particular colour can take several clicks, and a larger drawing repeats that effort across many cells. Reset clears the whole board; Exit leaves the experience."},{"type":"video","caption":"Original interaction recording: tutorial, repeated cell clicks, a painted heart and Reset. The activity suggestions use the same board."}]},{"title":"Design system","blocks":[{"type":"paragraph","text":"I built a shared colour palette, type styles, spacing scale and component library in Figma. The values below are the original design tokens: named colours and measurements reused across the screens. The controls show how the same system handles typing, hover, pressing and disabled states."},{"type":"paragraph","text":"One rule runs from the palette to the board: YellowishWhite (#FFFAEE) is the unpainted cell, and NeonLime (#C2EF34) is its third-click fill. The cell keeps its outlined square boundary as the fill changes. The board repeats that boundary and shows the same colour sequence in its legend."},{"type":"paragraph","text":"The buttons use a solid six-pixel shadow; the name field uses a four-pixel shadow. Their raised appearance carries through the interaction states. In the browser, submitting an empty name shows a correction and returns focus to the field."},{"type":"video","caption":"Original focused recording: the name field changes as text is entered, followed by the start-button interaction."}]},{"title":"Motion","blocks":[{"type":"paragraph","text":"I animated the title, tagline, geometric illustrations, dinosaur and birds using a small set of original shapes and poses. Reusing these parts keeps the entry and loading screens visually connected to the drawing board."},{"type":"video","caption":"Original entry animation: illustration and typography working together."},{"type":"video","caption":"Original loading recording. The browser uses a 4.5-second interval; the iteration chapter explains the timing change."},{"type":"paragraph","text":"The dinosaur and birds move by alternating poses. Controls use eased transitions, and the board dissolves on exit. Each motion has a role in the flow while using the same pixel style."}]},{"title":"Screen flow","blocks":[{"type":"paragraph","text":"The Figma prototype connects five scenes: enter a name, pass through loading, learn the colour rule, draw on the board, then leave or begin again. I placed a small tutorial before the full board to explain the colour cycle through a simpler example. The closing screen gives the open-ended activity a clear exit and return."},{"type":"paragraph","text":"Free Draw, Name Builder and Right–Wrong are suggestions for using the same board. They do not switch the underlying interaction or introduce separate scoring systems."},{"type":"video","caption":"Original exit and restart recording: the end of one creation leads back into the experience."}]},{"title":"Figma to browser","blocks":[{"type":"paragraph","text":"I completed the components and flow in Figma before exploring a browser build. I used vibe coding, working with AI to write and revise the code, to see how the same interaction would behave outside the prototype."},{"type":"paragraph","text":"I owned the concept, visual system, original assets, Figma design and interaction decisions. The browser code was co-created with AI assistance. I directed its review, checking timing, states and feedback against my design."},{"type":"paragraph","text":"The browser had to track painted cells, show Reset when there was something to clear, and handle exit and restart. A background of 409 animated squares uses a difference blend mode to extend the pixel style beyond the board."},{"type":"paragraph","text":"The browser scales a fixed-size stage to fit the window. Cell size, text readability, keyboard operation and touch targets still need a review across devices."}]},{"title":"Exhibition feedback","blocks":[{"type":"paragraph","text":"At the foyer exhibition, visitors from different design departments tried the board on an iPad and left written feedback. The photographs show people making a symmetrical pattern and lettering, with the system posters behind the device."},{"type":"paragraph","text":"Visitors used the same board for names, shapes, patterns and improvised shared activities. Their different uses supported keeping the board open-ended. The written comment about time, however, made repeated effort a priority to investigate rather than treating a simple rule as an easy interaction."},{"type":"points","items":[{"title":"Pace · faithful paraphrase","body":"On the first retained feedback sheet, a visitor liked trying the board but found it time-consuming, with an added note that it was engaging. This identifies friction without telling us whether waiting, colour selection or drawing caused it."},{"title":"Consistency · exact excerpt","body":"“Design system works as it should.” — anonymous written feedback, sheet 1. This is a visitor’s opinion of the system, rather than a measured usability result."},{"title":"Concept link · exact excerpt","body":"“Style is good but try and relate it with concept” — anonymous written feedback, sheet 2. The opening now explains how the square shapes controls, layout and motion, so the style has a visible connection to the activity."},{"title":"Refinement · faithful paraphrase","body":"Separate comments on the second sheet asked for more refinement and a clearer explanation of neo-brutalism. Other comments praised nostalgia, colour and interaction. These are separate observations, not one combined visitor quote."}]},{"type":"paragraph","text":"These excerpts come from two retained handwritten feedback sheets. The sheets do not establish a verified participant total or task record and remain private. This was an exhibition trial, not a structured usability study; no task-success rate or learning benefit was measured."}]},{"title":"Iterations","blocks":[{"type":"paragraph","text":"The documented timing change is from an eight-second loading scene in Figma to a 4.5-second browser interval. The animated scene carries the project’s character, but it also delays access to the board. Shortening it keeps that transition while reducing the fixed wait."},{"type":"comparison","before":"An eight-second loading scene.","after":"A 4.5-second loading interval.","note":"A documented timing revision. Its effect on waiting tolerance or task performance was not measured."},{"type":"paragraph","text":"Reset already has visible and hidden states in the Figma design. The browser shows it after a cell is painted and hides it when the board is clear. This is a state-based control: it appears when there is something to reset, rather than suggesting an action on an empty board."},{"type":"paragraph","text":"Exhibition use made touch a clearer priority for the next pass. I would review the rendered board, target sizes and repeated-tap effort directly on touch devices."},{"type":"paragraph","text":"In November 2026, I prepared a separate interaction comparison for the intended audience of general visitors and casual creative play. It keeps the same board and colours while separating cell cycling, choosing a colour, and continuous strokes. This new exploration is ready for a small moderated check; no participant sessions have been run."},{"type":"points","items":[{"title":"Original experience · entry and waiting","body":"Observe the live game from name entry through tutorial, the fixed loading interval, drawing and exit. This would show where someone hesitates, waits, needs help or leaves on an actual device."},{"title":"New comparison · painting effort","body":"The A/B/C lab removes the original entry, loading and animation. Its matched drawing tasks can examine colour selection and strokes, but cannot explain tolerance for the original wait."}]},{"type":"list","items":["Try the new painting comparison. New November 2026 exploration · Untested. A simplified local lab, separate from the original live game and exhibition evidence."]}]},{"title":"Pixel Pedia concept","blocks":[{"type":"paragraph","text":"Pixel Pedia is a companion mobile concept for discovering pixel games. I used it to explore how the same colours, typography and controls would work in search, lists, game cards and navigation. The drawing board tests the system around one repeated action; this concept explores it around finding and reading information."},{"type":"paragraph","text":"The extension introduces DM Mono for mobile interface copy while retaining the colour, outlined controls and pixel imagery. It was not evaluated as a separate product; its information hierarchy and reading experience remain questions for testing."}]},{"title":"Results and next steps","blocks":[{"type":"paragraph","text":"I made a reusable visual system, original illustration and animation assets, a five-scene Figma prototype and a playable browser exploration. Exhibition visitors gave the board different purposes. My main lesson was that an interaction can be easy to describe and still take effort to use: cycling one cell is simple, but drawing many cells makes repetition matter."},{"type":"paragraph","text":"The next evaluation has two parts: observe first use of the original complete game, then use the existing comparison for the same small-symbol, larger-block and recovery tasks in counterbalanced conditions. I would keep original-flow observations separate from the simplified lab results, make a justified change and check the affected task again. No such participant round or follow-up has run. Fill and saving remain future possibilities outside this exploration."},{"type":"paragraph","text":"I would use task completion, help, accidental changes and comments to decide what to retain, alongside action counts and time. Faster input alone would not establish a better creative experience; the choice also needs to preserve the board’s clarity and openness."}]}]},{"id":"syringe","title":"20 cc Syringe","contribution":"I developed the selected concept. My teammate and I shared the research and 3D-printed prototype work; my teammate created the Maya model.","duration":"4 weeks","summary":"We redesigned a 20 cc syringe for Indian healthcare practitioners, focusing on how they hold, operate and read it. I developed the selected concept; Varun Panda and I shared the research and 3D-printed prototype work over four weeks. My teammate created the Maya model.","overview":[],"sections":[{"title":"Design concept","body":[],"blocks":[{"type":"paragraph","text":"Our 20 cc syringe concept changes the thumb rest, finger flange, barrel grip and scale markings. The aim is to give smaller hands a more secure hold while keeping the dose visible. My teammate modelled it in Maya, and we 3D printed a prototype to explore its shape and contact with the hand."},{"type":"video","caption":"Concept presentation film · The physical prototype photographs below document the printed form."},{"type":"heading","text":"The physical prototype"},{"type":"heading","text":"Six changes to the contact surfaces"},{"type":"points","items":[{"title":"Concave thumb rest","body":"I curved the thumb rest inward to support the thumb pad when pushing the plunger."},{"title":"Butterfly finger flange","body":"Four rounded lobes give the fingers contact surfaces at different angles around the barrel."},{"title":"Transparent, ridged grip","body":"Ridges aim to help fingers hold the barrel while its transparent material keeps the fluid visible."},{"title":"Major rings, minor arcs","body":"Thick lines run around the barrel for major values. Thin, short curved marks keep the smaller readings from crowding the scale."},{"title":"Curved underside support","body":"Curves beneath the flanges support more of the thumb when drawing fluid, with the aim of spreading pressure over a wider area."},{"title":"Supported flange joints","body":"Reports of flange failure led me to add curved material where the flange joins the barrel. Its load capacity still needs testing."}]},{"type":"heading","text":"What the pilot ratings showed"},{"type":"comparison","before":"Physical effort stayed at 4.0/10. Plunger smoothness fell from 6.3 to 5.3 and perceived dosage accuracy from 6.7 to 5.0.","after":"Grip and thumb-strain impressions improved. Across all 21 attributes, 14 rated higher, two were unchanged and five rated lower.","note":"These are subjective impressions. The overall mean rose from 4.14 to 5.62/10, but it cannot outweigh a weaker result on control or dosing. The full results appear in Evaluation."},{"type":"paragraph","text":"Source: our HFID course report, p.14, Table 10. These are pilot questionnaire ratings, not measured clinical performance."},{"type":"paragraph","text":"We returned to the same hospital, where nurses tried the physical prototype and answered questions about how it felt in use. This Kansei Engineering questionnaire captures impressions of comfort and control; functional performance still needs task-based testing."}]},{"title":"Problem statement","body":[],"blocks":[{"type":"paragraph","text":"Indian healthcare practitioners with smaller hands can struggle to reach the plunger and keep a secure hold on a 20 cc syringe. Repeated thumb pressure, awkward wrist positions and slipping with gloves or wet hands were the problems we set out to address."},{"type":"points","items":[{"title":"74 mm working stroke","body":"The plunger travels 74 mm—92.5% of the 80 mm maximum thumb-to-index-finger span reported for a smaller Indian female hand (5th percentile). This leaves little spare reach."},{"title":"30–56 N reported injection force","body":"Published studies report this range for thick liquids, alongside an average thumb-to-fingertip pinch strength of 35.2 N for Indian adult women. We did not measure injection force."},{"title":"32 QEC wrist/hand score","body":"Our exploratory Quick Exposure Check (QEC), a posture-risk screening method, rated wrist and hand exposure as high. Practitioner feedback also described thumb-pad pressure, slipping and awkward wrist positions."}]},{"type":"paragraph","text":"Source: our HFID course report, p.7 for QEC and practitioner feedback; pp.8–10 for the literature and hand-measurement review. Literature force values were not measured on our prototype."},{"type":"heading","text":"The design question"},{"type":"paragraph","text":"How might we improve grip and thumb support for smaller Indian hands while keeping the syringe familiar to use?"}]},{"title":"Research and findings","body":[],"blocks":[{"type":"paragraph","text":"We combined published studies, a practitioner questionnaire, an exploratory posture-risk assessment and hand measurements. We measured existing syringes with a digital calliper, then grouped practitioner feedback into an affinity map to decide which parts of the design needed attention."},{"type":"heading","text":"Who contributed the evidence"},{"type":"table","caption":"Separate research records and unresolved sample information","headers":["Method","What is recorded","What remains unresolved"],"rows":[["Practitioner questionnaire","The paper describes routine syringe users and includes nurse, physician and laboratory-technician roles.","Pages 4 and 7 use 23 in prose but 25 in a profile table and chart caption. The response sheet must resolve that conflict; no single sample total is asserted here."],["Quick Exposure Check","A single assessment team recorded wrist/hand exposure of 32, alongside shoulder/arm and back scores.","Number of observed practitioners and agreement between independent assessors are not established. This is an exploratory exposure screen."],["Prototype pilot","The approved case records nurses handling the physical print and rating both devices across 21 terms.","Pilot rater count is unconfirmed. The paper describes existing-first order, but the exact execution and counterbalancing record remain incomplete."]]},{"type":"paragraph","text":"Method source: HFID paper pp.4, 6–7 and 20; physical-print account: approved interactive case, 19 October 2026. Questionnaire respondents and pilot raters are separate sample questions. Rounded ratings are not evidence of a particular pilot size."},{"type":"heading","text":"Holding and pushing needed different responses"},{"type":"paragraph","text":"Grip problems and pushing-force problems formed separate groups. Changing the parts that touch the hand could improve support and grip; reducing plunger force would also require work on the mechanism."},{"type":"points","items":[{"title":"Thumb pressure → support the thumb pad","body":"Literature and feedback described pressure over a small contact area. We explored inward-curved rests with rounded edges."},{"title":"Slipping → give fingers a secure hold","body":"Feedback about gloves and wet hands led us towards barrel ridges and curved flange surfaces."},{"title":"Posture and reading → keep the dose visible","body":"Reading the scale could require turning the barrel or changing grip. Thick major rings and short minor marks aimed to preserve a clearer hierarchy."},{"title":"Hand and device dimensions → check reach and clearance","body":"Plunger travel, contact width and ridge gaps need different hand measurements. We checked smaller-hand reach separately from space for larger fingers."}]},{"type":"heading","text":"Check reach and finger space"},{"type":"comparison","before":"5th-percentile female dimensions · Check reach and span: how far users need to stretch their fingers.","after":"95th-percentile male dimensions · Check contact and clearance: whether wider fingers have enough space.","note":"A later dimensional review found that some model dimensions needed revision. Those corrections are retained below."}]},{"title":"Design alternatives","body":[],"blocks":[{"type":"paragraph","text":"I explored the thumb rest, flange, barrel grip and scale as individual points of contact. Varun explored the syringe as a whole. We reviewed both approaches and selected my component-level concept for Maya modelling and 3D printing."},{"type":"heading","text":"My approach · Start with each point of contact"},{"type":"points","items":[{"title":"Push","body":"Inward-curved thumb rests respond to pressure at the thumb pad."},{"title":"Support","body":"The butterfly flange supports fingers from different angles."},{"title":"Hold","body":"Grip ridges and measured gaps aim to help with gloves and wet hands."},{"title":"Read","body":"Full major rings and short minor marks create two levels of emphasis."},{"title":"Draw fluid","body":"Curves beneath the flanges support more of the thumb."},{"title":"Apply load","body":"Curved joint supports respond to reports of flanges breaking or slipping under greater pressure."}]},{"type":"heading","text":"Varun’s approach · Consider the whole syringe"},{"type":"points","items":[{"title":"Wider palm support","body":"A broad wing would support the palm as well as the fingers."},{"title":"Transparent ridges","body":"Ridges made from the barrel material would keep the fluid visible."},{"title":"Colour-coded markings","body":"Dashed and coloured lines would emphasise selected measurements."}]},{"type":"heading","text":"The selected direction"},{"type":"paragraph","text":"My component-level concept moved forward. Its grip, thumb support, flange shape, joint supports and scale were carried into the Maya model and printed prototype. Varun’s sketches remained an alternative; we continued the research and development together."},{"type":"paragraph","text":"That selection narrowed what we built to the contact surfaces and scale. It did not introduce a new force-reducing mechanism or shorten the 74 mm stroke, so the original concerns about effort and reach remained open."},{"type":"heading","text":"A current review of the trade-off"},{"type":"comparison","before":"A whole-form wing could bring the palm into the support area, but it also changes the overall hold and would need its own dimensional and handling checks.","after":"The component route keeps the familiar barrel and makes thumb, finger and scale details easier to inspect separately. It also leaves the original stroke and actuation mechanism unchanged.","note":"Retrospective design review · November 2026. This explains the scope I would assess now; it is not a recovered historical selection test. My concept remains the selected direction, with shared research and development credited to Varun and me."}]},{"title":"Form and dimensions","body":[],"blocks":[{"type":"paragraph","text":"I developed the selected concept around three decisions: distinguish major and minor scale marks, support the thumb when pushing and drawing fluid, and strengthen the flange connections. The dimensional review below also identifies parts that still need resizing."},{"type":"points","items":[{"title":"Wrap the major lines","body":"Thick rings keep major values visible around the barrel. Thin, short curved brackets prevent the smaller readings from filling the surface with lines."},{"title":"Support the thumb in both directions","body":"The concave plunger rest supports pushing; underside flange curves support the thumb while drawing fluid."},{"title":"Support the flange connection","body":"Curved material at the joints was included in the model. Its load capacity still needs testing."}]},{"type":"comparison","before":"If every scale mark wrapped around the barrel, the additional lines could make small readings harder to identify.","after":"Use two levels of emphasis: thick full rings for major values and thin, short arcs for minor readings.","note":"The design aims to keep detail readable. Scale-reading accuracy remains a separate testing question."},{"type":"heading","text":"Dimensioning the contact points"},{"type":"table","caption":"Current form and proposed requirements · HFID paper Tables 7–8","headers":["Part or requirement","Current record","Proposed direction","Status"],"rows":[["Flange contact land per finger","16 mm","At least 22 mm in the paper’s larger-finger accommodation review","Revision proposed; revised model and hand-fit check not completed"],["Gap between grip ribs","16 mm","At least 22 mm in the paper’s clearance review","Revision proposed; actual glove allowance still needs checking"],["Thumb rest","18 mm diameter, inward-curved","The paper proposes at least 25 mm using a pressure criterion","Contour and contact pressure may change the requirement; measure before fixing a new diameter"],["Total flange span","Not specified in the recorded model table","60–65 mm proposed in the paper","Needs explicit dimensioning and hand-fit review"],["Working stroke","74 mm","Paper proposes at most 70 mm, with 60 mm preferred","Unchanged; any capacity/geometry revision remains a new design task"],["External grip diameter","22.5 mm in the paper’s comparison","25–30 mm contoured sleeve proposed","Partially addressed; added bulk versus grip needs checking"],["Actuation effort","No force measurement or assist mechanism","Measure the required effort before selecting a mechanical change","Unresolved; reshaping contact surfaces does not demonstrate lower force"]]},{"type":"paragraph","text":"The proposed values are the paper’s design hypotheses, not dimensions validated by this print. The thumb-rest question is especially useful: a smaller concave rest received a better strain rating, but that does not tell us its contact pressure. I would test the actual contact and hand fit before treating any target as settled."},{"type":"heading","text":"What still needs revision"},{"type":"paragraph","text":"The flange contact width and gap between grip ridges are both 16 mm; the revised requirement is at least 22 mm. The plunger stroke remains 74 mm. Thumb pressure should be measured before choosing a new thumb-rest diameter."},{"type":"paragraph","text":"Designing for smaller hands does not mean making every part smaller. Reach has to work for smaller hands, while contact surfaces and gaps also need room for larger fingers. The 16 mm widths did not meet that revised requirement; the new shape alone did not resolve hand fit."},{"type":"paragraph","text":"We still need to measure thumb pressure and joint load. The current contact changes should not be treated as proof of reduced plunger effort."}]},{"title":"Physical prototype","body":[],"blocks":[{"type":"paragraph","text":"My teammate built the selected concept in Autodesk Maya. We then worked on the 3D-printed prototype together. The model brought the barrel, scale and redesigned contact surfaces together; the print let us examine size, grip position and contact with the hand."},{"type":"heading","text":"Resolve the form in three dimensions"},{"type":"heading","text":"Bring the concept into the hand"},{"type":"paragraph","text":"The print has a transparent body and black plunger. These views document the physical form and different hand positions."},{"type":"paragraph","text":"Holding the print made its size and contact points tangible. We then returned to the hospital for the pilot evaluation."},{"type":"paragraph","text":"The approved case confirms that nurses handled the physical print. The retained records do not establish whether it had a working fluid path. I therefore separate holding and appearance impressions from any claim about moving fluid or delivering a dose."}]},{"title":"Pilot evaluation","body":[],"blocks":[{"type":"paragraph","text":"The pilot gave mixed results. Nurses rated the grip more favourably, but physical effort stayed at 4.0/10. Plunger smoothness fell from 6.3 to 5.3, and perceived dosage accuracy fell from 6.7 to 5.0. These findings made control and dosing priorities for the next version."},{"type":"paragraph","text":"Nurses tried the physical prototype at the same hospital, then rated how it felt using a Kansei Engineering questionnaire. We compared the existing syringe and prototype across 21 attributes on a 1–10 scale. Higher means a more favourable impression, including less slipping or strain for those terms."},{"type":"paragraph","text":"The pilot rater count is unconfirmed. The paper describes rating the existing syringe first and prototype second; its limitations qualify that account, and execution/counterbalancing records are incomplete. We cannot infer a sample size from the rounded means."},{"type":"paragraph","text":"Because a working fluid path is not established, the smoothness, control and dosage ratings may reflect handling or expectation rather than an executed dosing task. They still identify questions to investigate; they do not measure delivered-dose error."},{"type":"heading","text":"Effort and dosing remain open"},{"type":"points","items":[{"title":"Physical effort · 4.0 → 4.0","body":"The contact shape changed, but the physical-effort rating stayed the same. Any claim of lower effort would need a force measurement and, potentially, a change to the mechanism."},{"title":"Plunger smoothness · 6.3 → 5.3","body":"The lower rating makes plunger movement a testing priority. A more secure grip does not by itself establish smooth movement."},{"title":"Dosage accuracy · 6.7 → 5.0","body":"Test dose setting from different viewing angles and measure the fluid delivered. The rating identifies a concern; it does not quantify a dosing error."}]},{"type":"heading","text":"Grip impressions improved"},{"type":"paragraph","text":"Grip slipperiness and thumb strain ratings each rose by 4.7 points; glove usability rose by 4.0. These were areas we aimed to improve, but we did not test each design feature separately."},{"type":"heading","text":"Read the overall mean alongside those trade-offs"},{"type":"points","items":[{"title":"4.14 → 5.62 / 10","body":"Mean across all 21 attributes: a rise of 1.48 rating points. The project paper reports this as a 35.7% higher mean relative to the original. It is a change in subjective ratings, not a measured physical benefit."},{"title":"14 higher · 2 unchanged · 5 lower","body":"The overall mean does not show every trade-off. Grip and comfort improved in the ratings, while effort and dosing remained open."},{"title":"Subjective pilot evaluation","body":"These ratings describe nurses’ impressions. They do not measure injection force, thumb pressure, wrist angles or the amount of fluid delivered."}]},{"type":"heading","text":"All 21 attributes"},{"type":"table","caption":"Table 10 · Mean ratings out of 10; higher is more favourable. Change is in rating points.","headers":["Attribute","Existing syringe","Prototype","Change"],"rows":[["Grip slipperiness","2.3","7.0","+4.7"],["Thumb strain","2.0","6.7","+4.7"],["Glove usability","2.0","6.0","+4.0"],["Finger strain","3.0","6.3","+3.3"],["Secure hold","3.7","6.7","+3.0"],["One-hand use","2.7","5.7","+3.0"],["Hand stability","3.3","6.0","+2.7"],["Measurement readability","4.0","6.0","+2.0"],["Pain level","4.0","5.7","+1.7"],["Hand fatigue","3.3","5.0","+1.7"],["Wrist posture","3.7","5.3","+1.6"],["Overall comfort","4.3","5.7","+1.4"],["Overall design","5.7","6.3","+0.6"],["User confidence","5.7","6.0","+0.3"],["Physical effort","4.0","4.0","0.0"],["Safety feeling","5.7","5.7","0.0"],["Plunger force","4.3","4.0","−0.3"],["Usage strain","5.0","4.7","−0.3"],["Plunger control","5.3","5.0","−0.3"],["Plunger smoothness","6.3","5.3","−1.0"],["Dosage accuracy","6.7","5.0","−1.7"],["Mean across all terms","4.14","5.62","+1.48"]]},{"type":"heading","text":"Separate perception from performance"},{"type":"paragraph","text":"Measurement readability rose from 4.0 to 6.0, while dosage accuracy fell from 6.7 to 5.0. The ratings describe different things: being able to read the markings and feeling able to set a dose accurately. That disagreement is a reason to test the complete dosing task, rather than treating the clearer-looking scale as a finished improvement."},{"type":"paragraph","text":"Fit across the full hand-size range remains unconfirmed. A follow-up study should measure task performance and vary which syringe each participant tries first to check for an order effect."}]},{"title":"Reflection and next steps","body":[],"blocks":[{"type":"paragraph","text":"The pilot gave us more favourable grip ratings, but effort stayed the same and dosage accuracy rated lower. I would revise hand fit and test dose setting, pressure and force before taking the concept further."},{"type":"points","items":[{"title":"Break down the interface. Keep the task in view.","body":"Major rings and short minor marks aim to reduce scale clutter. Their value still depends on whether users can read and set a dose accurately."},{"title":"Evaluate comfort, control and effort separately.","body":"Grip ratings improved, effort stayed the same and dosage accuracy rated lower. Each result needs attention; the overall mean cannot replace them."},{"title":"Check who each dimension fits.","body":"We initially used female 95th-percentile measurements for finger space. A later check against larger male fingers showed that the 16 mm contact width and ridge gaps were too small. I would check smaller and larger hands before finalising dimensions."}]},{"type":"heading","text":"What I would test next"},{"type":"points","items":[{"title":"Dose setting · mL and percentage error","body":"Compare a working prototype with the existing syringe using a reference scale. Test readings from several angles and weigh the delivered fluid."},{"title":"Pressure and effort · kPa and newtons","body":"Use pressure-sensitive film for thumb pressure and a force gauge for plunger effort. Use those results to revise the thumb rest and any mechanism intended to reduce effort."},{"title":"Hand fit, posture and slip","body":"Include practitioners with smaller and larger hands, record their measurements and vary the testing order. Revisit contact widths, ridge spacing and plunger travel alongside repeat ratings."}]},{"type":"paragraph","text":"I would resolve the contact dimensions before that next round, then prioritise dose setting and plunger movement because their pilot ratings fell. Repeat comfort ratings alongside the task measurements so a better overall impression cannot hide a weaker result on a critical part of use."},{"type":"heading","text":"Presenting the work at Meraki"},{"type":"paragraph","text":"We presented the research and 3D-printed prototype at Meraki. Jurors appreciated the depth of the work and our explanation of the design."},{"type":"paragraph","text":"The redesign was also shortlisted after the first review round for research-paper presentation at HWWE 2026. The December 2026 event is still ahead at the time of this case update, and publication remains subject to jury review."}]}]},{"id":"connectaid","title":"ConnectAid","contribution":"I co-designed the app, built its core Figma design system and coordinated remote usability testing.","duration":"8 weeks","summary":"ConnectAid is a mobile healthcare prototype for consultations, medicines, lab tests and health records. In our eight-week, five-person project, I built the core Figma design system and coordinated remote usability testing. We later reviewed parts of the design again in October 2026.","overview":[{"type":"heading","text":"How the sprint fit the eight weeks"},{"type":"paragraph","text":"Research and synthesis came before an adapted five-day sprint. We continued design, testing and refinement across the eight-week project."},{"type":"points","items":[{"title":"Before the sprint · Research and synthesis","body":"Interviews, a survey, a healthcare-app review and grouped findings."},{"title":"Day 1 · Frame","body":"How might we questions, goals and the care journey."},{"title":"Day 2 · Sketch","body":"Crazy 8s, critique and concepts."},{"title":"Day 3 · Storyboard","body":"Plan the test flow and begin the prototype."},{"title":"Day 4 · Prototype","body":"Build the prototype and prepare for testing."},{"title":"Day 5 · Test preparation","body":"Prototype checks and the user-testing agenda."},{"title":"After the sprint · Continued design work","body":"Build screens, review, test usability and refine the prototype."}]},{"type":"paragraph","text":"The sprint was one part of the project. The remote usability sessions and continued refinements were not all completed on the fifth day."}],"sections":[{"title":"The prototype","body":[],"blocks":[{"type":"paragraph","text":"ConnectAid brings booking consultations, finding medicines and lab tests, and returning to health records into one app prototype. Home is the starting point for care services; Records stays in the main navigation for use after a visit."},{"type":"points","items":[{"title":"Review before booking","body":"The doctor, appointment, patient options and total fee appear together before payment."},{"title":"Keep records within reach","body":"Prescriptions, reports and other health information have a dedicated Records section."},{"title":"Return to a prescription","body":"Each prescription entry identifies the doctor, patient and date."}]},{"type":"heading","text":"What testing changed"},{"type":"paragraph","text":"Remote usability testing with six participants covered 11 scripted tasks. Nine documented findings led to six refinements across navigation, data entry and task controls."},{"type":"points","items":[{"title":"Finding services","body":"More visible navigation and another route to the lab-test listing."},{"title":"Entering details","body":"Revised date entry and the ability to search by doctor specialty."},{"title":"Moving through tasks","body":"A repositioned cart and lighter side-panel content in the prototype."}]},{"type":"paragraph","text":"All screens use sample content. The outcome is a designed and tested prototype, not a launched healthcare service; the Usability testing chapter shows what we changed and what remains unverified."}]},{"title":"Problem statement","body":[],"blocks":[{"type":"paragraph","text":"People arranging care for themselves or a family member faced three questions: can this need be handled online, who can I trust, and where will my prescriptions and reports go afterwards? Our survey and interviews surfaced concerns about virtual care, unfamiliar doctors and sharing medical information. The prototype connects care options, booking details and records so those decisions can be made in one place."},{"type":"paragraph","text":"We designed for adults arranging their own or a family member’s care. Independent use by older adults and use in languages other than English were design goals, rather than audiences established by our testing."},{"type":"heading","text":"The four care tasks"},{"type":"points","items":[{"title":"Consultations","body":"Book online and in-clinic visits."},{"title":"Medicines","body":"Order medicines."},{"title":"Lab tests","body":"Find tests and scans."},{"title":"Health records","body":"Return to prescriptions and reports."}]},{"type":"paragraph","text":"We organised consultations, medicines and lab tests around Home, and kept health records in the main navigation. The goal was to help people book care for themselves or a family member and access their records afterwards."},{"type":"heading","text":"Three priorities"},{"type":"points","items":[{"title":"Clear booking details","body":"Make the patient, appointment and total fee clear before confirmation."},{"title":"Records after the visit","body":"Keep prescriptions and reports easy to find."},{"title":"Language choice","body":"Keep language switching available beyond initial setup."}]}]},{"title":"User research","body":[],"blocks":[{"type":"paragraph","text":"We used a survey, interviews and a review of four healthcare apps to understand how people chose care and what concerned them about online consultations."},{"type":"points","items":[{"title":"Survey · 189 submissions","body":"Healthcare habits, previous telemedicine use and concerns. Of these, 114 were aged 21–30 and none were over 60; answers about older relatives were indirect."},{"title":"Interviews · 5 documented","body":"How people chose doctors, involved family and described their difficulties. The case records themes, but does not establish the interviewees’ age, language or digital-confidence coverage."},{"title":"Competitive review · Four apps","body":"Navigation, screen content, service discovery and doctor information."},{"title":"Later usability study · 6 participants","body":"Remote, moderated use of our prototype across 11 tasks. This is a separate sample from discovery; its demographic coverage is not documented here."}]},{"type":"heading","text":"Previous use and concerns"},{"type":"paragraph","text":"Before testing our prototype, 103 of 189 survey submissions (54.5%) selected “I have never used telemedicine”."},{"type":"points","items":[{"title":"Limits of virtual care · 64.0%","body":"121 of 189 submissions selected concern about medical issues that cannot be solved virtually."},{"title":"Missing medical equipment · 47.1%","body":"89 of 189 submissions selected the absence of equipment for taking readings."},{"title":"Trust in unfamiliar doctors · 31.2%","body":"59 of 189 submissions selected this concern."},{"title":"Data privacy · 27.0%","body":"51 of 189 submissions selected this concern."}]},{"type":"paragraph","text":"The survey allowed multiple selections. One submission selected both “never used” and a usage option. Two written “No” answers were not added to the 103 selections."},{"type":"heading","text":"What the interviews added"},{"type":"points","items":[{"title":"Remote care was not always called telemedicine","body":"Some people described contacting doctors through WhatsApp and calls without identifying this as telemedicine."},{"title":"Familiar doctors influenced trust","body":"Interview notes described a preference for known doctors and their referrals to specialists."},{"title":"Sharing records raised privacy concerns","body":"People saw value in sharing medical information but were concerned about sharing it online."}]},{"type":"heading","text":"Healthcare-app comparison"},{"type":"paragraph","text":"We compared Tata 1mg, DocOn, Practo and Apollo. This was a qualitative project review of service discovery, navigation and doctor information."},{"type":"points","items":[{"title":"Tata 1mg · Home","body":"Our review noted a long home page with extensive scrolling."},{"title":"DocOn · Doctor details","body":"The profiles included useful experience, education and specialisation information."}]},{"type":"heading","text":"From findings to screens"},{"type":"points","items":[{"title":"Virtual care had limits → keep care options visible","body":"With 121 of 189 submissions concerned about issues that cannot be handled virtually, we kept clinic and lab routes alongside online consultations on Home."},{"title":"Unfamiliar doctors raised concern → show details before booking","body":"Interviewees valued known doctors and referrals. We showed specialty, experience, ratings and patient stories before confirmation so people had information to consider before committing."}]},{"type":"paragraph","text":"These choices respond to the research. We did not measure whether they changed trust or increased telemedicine use."}]},{"title":"Research findings","body":[],"blocks":[{"type":"paragraph","text":"The research pointed to three needs: useful doctor information before booking, follow-up guidance after a visit, and easy access to prescriptions and reports. We grouped the research notes, created two personas and mapped a planned care journey to turn these needs into design priorities."},{"type":"heading","text":"The patterns behind the priorities"},{"type":"paragraph","text":"The affinity map groups research notes and proposed features into 12 topics. Booking was only one part of the activity: reports from a lab could be needed at a follow-up, and prescriptions needed to remain available after the consultation."},{"type":"heading","text":"Two personas to guide decisions"},{"type":"paragraph","text":"We used two fictional personas to consider independence, language preference and time constraints. Their names and profiles are synthesised design tools, not identified research participants."},{"type":"points","items":[{"title":"Shekhar Gupta · 73 · Retired librarian · Dehradun","body":"Wants to manage regular care independently: book appointments, find prescriptions and access reports from regular tests. Design focus: clear booking steps and records that are easy to find. The survey contained no respondents over 60, so this older-adult profile had indirect support."},{"title":"Rajesh Patel · 42 · Businessman · Jamnagar","body":"Needs to fit care around a busy workday. Comfortable with Gujarati and Hindi, with limited English. Design focus: simple booking steps, clear labels and an accessible language choice."}]},{"type":"heading","text":"The planned care journey"},{"type":"paragraph","text":"The planned journey follows a consultation into lab tests and a follow-up, rather than ending at the first booking."},{"type":"list","items":["Create a profile: add personal details and medical history.","Book a doctor: review the doctor, choose a time and confirm.","Attend the consultation: discuss symptoms, treatment and any required tests.","Complete tests: choose a lab, complete the tests and get reports.","Follow up: share reports and discuss the next steps."]},{"type":"paragraph","text":"That connection shaped the navigation: Home starts a new care task, while Records remains a main destination for returning to earlier information. The journey map helped us connect those tasks instead of designing each service as an isolated flow."}]},{"title":"Priorities and scope","body":[],"blocks":[{"type":"paragraph","text":"We prioritised clear doctor information, language choice, records and the routes between care tasks. During an adapted five-day sprint, we used questions, team voting and an impact–effort matrix to decide what to prototype."},{"type":"heading","text":"Questions the sprint focused on"},{"type":"paragraph","text":"We wrote How might we questions and used team voting to focus the sprint. The highlighted questions concerned medicine information, organised records, independent use, language and access needs."},{"type":"heading","text":"Compare value with effort"},{"type":"paragraph","text":"We used an impact–effort matrix to compare the value of ideas with the work needed to prototype them. The positions were team estimates. Appointment booking and doctor information were relatively direct to explore; language support, records and delivery involved a wider set of screens and service questions."},{"type":"points","items":[{"title":"Quick wins · Higher impact, lower effort","body":"Appointment scheduling, doctor reviews and medicine reminders."},{"title":"Major projects · Higher impact, higher effort","body":"Language switching, profiles and medical records, and medicine delivery."},{"title":"Smaller additions · Lower impact, lower effort","body":"A discussion forum and referral benefits."},{"title":"More effort, less impact","body":"Smart-device integration."}]},{"type":"heading","text":"The routes selected for prototyping"},{"type":"points","items":[{"title":"Consultations","body":"Home, then doctor information, then booking review."},{"title":"Lab tests","body":"Home, then tests and scans."},{"title":"Records","body":"Open Records, then Prescriptions."}]},{"type":"paragraph","text":"We took consultation, lab and record routes into the sketches. The matrix also kept wider ideas visible without implying that every idea—such as smart-device integration or a discussion forum—was delivered in the prototype."}]},{"title":"Sketches and storyboards","body":[],"blocks":[{"type":"paragraph","text":"We sketched alternatives for Home and the main care tasks, compared them as a team, then connected selected ideas into storyboards. Crazy 8s—a rapid sketching exercise—helped us explore several layouts before choosing a direction."},{"type":"heading","text":"Compare layout alternatives"},{"type":"paragraph","text":"The team sketched different layouts for Home and key care tasks, then voted on ideas to develop further."},{"type":"heading","text":"Language choice should stay within reach"},{"type":"paragraph","text":"The critique noted that language switching should remain discoverable later in the journey. We kept the language control on Home beyond initial setup. This was design-team feedback, rather than a measured user-test result."},{"type":"heading","text":"Sketch the lab-booking task"},{"type":"points","items":[{"title":"Find a test","body":"Test search and lab suggestions based on location."},{"title":"Compare the labs","body":"Cards with test price, distance and lab information."},{"title":"Plan the booking","body":"Test, date, time, location and report format."}]},{"type":"heading","text":"Connect the lab-booking steps"},{"type":"paragraph","text":"The storyboards connected selected ideas before we built the interactive flows. The lab-booking sequence moves from finding a test to completing and returning to a booking."},{"type":"list","items":["Lab home","Test search","Lab list","Lab details","Test selection","Test details","Booking preferences","Payment","Confirmation","Saved booking"]},{"type":"paragraph","text":"The first five steps find the test and choose a lab. The next five review details, enter booking preferences, pay and return to the saved booking. The complete board also explores Home, language switching, profiles, medicines and appointments."}]},{"title":"Design system","body":[],"blocks":[{"type":"paragraph","text":"I built the core Figma design system: shared colours, Work Sans type styles and reusable components. The team used these foundations to build consistent screens. The original foundations and later screen refinements are shown separately below."},{"type":"heading","text":"A shared palette"},{"type":"points","items":[{"title":"Primary · ConnectAid Blue · #00A5CF","body":"The original cyan foundation for the product."},{"title":"Secondary · ConnectAid Orange · #FB714E","body":"A secondary colour in the shared palette."},{"title":"Neutral · #333333","body":"Part of the neutral text and surface scale."},{"title":"Status and base tokens","body":"Success #00CF6E; warning #F79009; error #F04438; white #FFFFFF; black #000000."}]},{"type":"paragraph","text":"These values come from the original Figma fills and component variables. We keep the original system visible here so its role in the screens is clear; the October review below shows where the action colours needed correction."},{"type":"heading","text":"Work Sans across the screens"},{"type":"paragraph","text":"Work Sans was the product typeface for headings, titles and body text. Defined sizes and line heights gave the screens a shared hierarchy."},{"type":"points","items":[{"title":"Heading · Size / line height in px","body":"32/40, 28/36 and 24/32."},{"title":"Subheading","body":"24/32, 20/28 and 18/24."},{"title":"Title","body":"18/24, 16/20 and 14/18."},{"title":"Body","body":"16/20, 14/18 and 12/16."}]},{"type":"heading","text":"Buttons for different states"},{"type":"paragraph","text":"The component library defined regular, hover, focused and inactive states. Four sizes—XS, SM, MD and LG—and four hierarchies—primary, secondary, tertiary and link—supported different actions and available space. Separate destructive variants distinguished actions such as deletion."},{"type":"paragraph","text":"The original white-on-cyan button label measures 2.88:1 contrast. The later product screens use darker action colours; those changes do not establish a whole-product accessibility pass."},{"type":"heading","text":"Components in the updated interface"},{"type":"paragraph","text":"The test-list screen shows how the pieces work together: search and filters narrow the list, each card gives preparation and price information, and Add is the next action. These are actual updated-screen details using the later colour refinements."},{"type":"paragraph","text":"The evidence covers the original button-state family and selected updated screen instances. It does not show a complete corrected library across hover, focus, inactive and destructive states. The next system check is to trace the darker action colour from the shared component through those states into the booking and test-list screens."}]},{"title":"Usability testing","body":[],"blocks":[{"type":"paragraph","text":"We ran remote, moderated sessions with six participants across 11 scripted tasks. Tasks covered setup, language switching, consultations, medicines, lab tests, prescriptions and the SOS concept. The study documented nine findings and led to six design refinements."},{"type":"heading","text":"The nine documented findings"},{"type":"list","items":["Date-of-birth entry was difficult with the calendar.","Participants overlooked the bottom navigation.","Participants preferred English and were reluctant to switch languages in these sessions.","A slowly loading side panel prompted repeated, unintended clicks.","The list of available lab tests was hard to find.","Adding items to the cart required repeated scrolling.","Participants tried searching by doctor specialty instead of following the intended category route.","Prescription details were difficult to reach when the bottom navigation was overlooked.","Participants had trouble finding the list of lab-test bookings."]},{"type":"heading","text":"Six refinements"},{"type":"comparison","before":"Date of birth: participants had difficulty entering a birth date with the calendar.","after":"We replaced calendar browsing with separate day, month and year selection, so people could enter the date they already knew without browsing month by month.","note":"Date-entry control → separate values for a known date. The before/after artifact below shows the change; no comparative completion-time result was recorded."},{"type":"comparison","before":"Specialty search: participants searched for the doctor’s specialty rather than using the category route.","after":"We enabled search by specialty while retaining category browsing. This supported the terms participants tried instead of requiring them to follow our chosen category route.","note":"Doctor discovery → search and browsing both remain available. This follows the route participants actually tried; keeping both means their specialty labels and destinations must agree."},{"type":"comparison","before":"Lab-test discovery: participants had trouble finding the list of tests.","after":"We connected View all beside Popular Tests to the test listing, while retaining the main booking entry.","note":"Lab services → View all and the main booking entry lead to the same listing. We added a route at the point people were already exploring tests."},{"type":"comparison","before":"Bottom navigation: participants overlooked the navigation and missed routes to records.","after":"We made the active destination indicator more prominent.","note":"Shared navigation → a stronger active state. The source artifact shows this visual change; prescription and booking-history retrieval still need a task check."},{"type":"points","items":[{"title":"Cart · Bring the control into view","body":"Adding items required repeated scrolling. We repositioned the cart control to make it easier to reach."},{"title":"Side panel · Reduce prototype delay","body":"The panel responded slowly and prompted repeated clicks. We reduced the content beneath the overlay in the prototype. This addressed the Figma interaction, rather than demonstrating a production performance improvement."}]},{"type":"paragraph","text":"These six changes trace the finding summary to a revised control or route. The available case records do not include verbatim task prompts, per-participant observations, device details or a definition of completion and assistance. We therefore report the issues and changes, rather than reconstructing a success rate or ranking them by an unknown frequency."},{"type":"heading","text":"What the changes did not settle"},{"type":"paragraph","text":"A stronger navigation indicator is a visible design change, but it does not establish that people can now find prescriptions or lab-booking history. The source does not show a separate change for booking history. Those tasks still need to be checked."},{"type":"paragraph","text":"Participants preferred English in these sessions. We kept language choice available, but this study does not establish how well the other language flows work. Some users informally reviewed the refinements; there was no comparable second study or measured improvement in task completion."}]},{"title":"Final screens and flows","body":[],"blocks":[{"type":"paragraph","text":"The high-fidelity screens focus on consultation review, lab-test discovery and prescription access. These exports include the later colour refinements. Names, clinician profiles, dates, offers, prices and prescription content are prototype examples."},{"type":"heading","text":"From Home to a prescription"},{"type":"list","items":["Home: open Records from the bottom navigation.","Health Records: choose Prescriptions from the record categories.","Prescriptions: identify the entry, then select View Prescription."]},{"type":"heading","text":"Review the appointment before payment"},{"type":"points","items":[{"title":"Appointment","body":"The doctor, date and time appear before confirmation."},{"title":"Patient","body":"Patient profiles and the Myself control identify who needs care. The later review questions this duplicated control."},{"title":"Cost","body":"The fee, extra charges and total are shown separately in the video-consultation review."}]},{"type":"heading","text":"Find and compare lab tests"},{"type":"points","items":[{"title":"Explore lab services","body":"Booking, reports and lab locations are available from the lab-services screen."},{"title":"Choose from the test listing","body":"Search and filters sit above test cards with prices, preparation details, collection options and an Add action."}]},{"type":"paragraph","text":"This is a high-fidelity portfolio prototype. It does not provide live consultations, medicine ordering, lab booking, emergency response or payment processing."}]},{"title":"October 2026 review","body":[],"blocks":[{"type":"paragraph","text":"In October 2026, we reviewed contrast and patient selection after the original project. Darker colours were applied to the updated product screens. The patient-selection and payment changes below remain proposals."},{"type":"heading","text":"Improve action-label contrast"},{"type":"comparison","before":"Original colour pair: white text on #00A5CF measures 2.88:1.","after":"Refined colour pair: white text on #005982 measures 7.63:1.","note":"Ratios apply to these shown text/background pairs. They do not certify the whole product."},{"type":"paragraph","text":"The later review also proposed #B42318 for destructive actions, measuring 6.57:1 with white text. Selected supporting grey text was darkened from #808080 to #666666. These were targeted colour corrections."},{"type":"heading","text":"Proposed patient selection"},{"type":"comparison","before":"The original review screen presents patient cards and a separate Myself control.","after":"The proposal uses one choice for the account holder or a family member. Selecting another person replaces the current choice.","note":"A proposed interaction, not a tested final implementation."},{"type":"paragraph","text":"The patient-selection proposal uses Myself · Abhay Parikh (51 years) and Divya Parikh (family member, 22 years) as sample options. One selected state should make the patient clear without asking the same question twice."},{"type":"heading","text":"Proposed payment readiness"},{"type":"paragraph","text":"In the payment-readiness proposal, Confirm & Pay becomes available after a payment method is selected. The specimen separates the ₹1,000 clinic consultation and ₹49 service charge, for a total of ₹1,049. UPI is an illustrative option; the specimen does not process payments."},{"type":"points","items":[{"title":"No method selected","body":"Explain that a payment method is needed before continuing. Keep Confirm & Pay unavailable."},{"title":"Method selected","body":"Enable the next action while keeping the selected patient and total visible."}]},{"type":"paragraph","text":"Both proposals address a decision before commitment: who the appointment is for and what must happen before payment. The next study should check whether people understand the selected patient, the total charge and when payment becomes available."}]},{"title":"Outcomes and next steps","body":[],"blocks":[{"type":"paragraph","text":"We delivered a tested healthcare prototype and made six refinements in response to the usability findings. The later review also improved selected colour pairs and proposed clearer patient and payment choices. We still need to test the revised tasks before claiming that they are easier to complete."},{"type":"points","items":[{"title":"Support more than one starting point","body":"Participants searched by specialty and looked for different routes to lab tests. Search and browsing should remain available with consistent labels and destinations."},{"title":"Check accessibility before reuse","body":"Shared components kept screens consistent, but the later review found low button contrast. Contrast and interaction states need checking when the components are defined."},{"title":"Resolve the core before adding more","body":"Booking and records need further testing before live waiting information or other integrations. Patient selection, total charges and access to records come first."},{"title":"A revision still needs evidence","body":"Testing led to six refinements and informal feedback followed, but improvement was not measured. Another study should include different levels of digital confidence."}]},{"type":"heading","text":"Test the tasks that caused difficulty"},{"type":"paragraph","text":"First, compare the original and revised flows for date-of-birth entry, specialty search and lab-test discovery. Then check whether people can retrieve prescriptions and lab-booking history. Include people with lower digital confidence and different language preferences, rather than treating the first sessions as coverage of those needs."},{"type":"list","items":["Task completion","Time taken","Assistance needed"]},{"type":"paragraph","text":"Use those results to decide which routes need another revision. Keep the proposed patient and payment changes in that next study before expanding into more services."}]}]},{"id":"giggles","title":"Giggles","contribution":"I built the electronics, programmed the game rules and made the working prototype. Teammates designed the interface screens; I helped review and direct them.","duration":"6-week course project; later testing","presentation":{"generated":true,"description":"AI-generated presentation mockup based on our board, cards and interface designs. Actual build photographs are in the full case study."},"summary":"Giggles is a learning board game for autistic children. A phone shows each question; players answer by tapping a card on the reader or pressing a physical shape. I built the electronics, game logic and working prototype during the six-week project; teammates designed the interfaces, which I helped review. Testing at Vishwansh Foundation showed where the instructions, shared screen and turns needed to be clearer.","overview":[],"sections":[{"title":"The game","body":[],"blocks":[{"type":"paragraph","text":"A player rolls the die, moves a pawn and activates a learning category. A phone shows the question. The player answers with an RFID card, which the electronic reader recognises, or by pressing a matching shape. Lights, speech and on-screen feedback respond before the next turn."},{"type":"points","items":[{"title":"Communication","body":"Choose a phrase for an everyday situation, such as asking for help or setting a boundary."},{"title":"Emotion","body":"Match the activity’s expected emotion to an illustrated question."},{"title":"Shapes and physical response","body":"Find and press a matching shape, combining visual comparison with a tangible action."}]},{"type":"paragraph","text":"The working prototype runs the child-facing game, manages three-player turns and holds the current game state. The wider concept adds saved individual records and a Teacher App; these were not connected to the final electronics prototype."},{"type":"points","items":[{"title":"What the visit examined","body":"Could participants follow a turn, choose a physical answer and understand the game’s feedback with teacher support? The trial exposed instructions, screen visibility and sensor problems in that loop."},{"title":"What remains a proposal","body":"Helping educators compare independent answers, hints and support across sessions requires saved records and a connected teacher view. The classroom visit did not evaluate that wider service."}]}]},{"title":"Problem statement","body":[],"blocks":[{"type":"paragraph","text":"A correct answer alone does not tell an educator how a child reached it: independently, after several attempts or with a hint. Our design challenge was to make communication, emotion and shape practice clear and hands-on for autistic learners, while giving educators a way to understand the support behind each answer. We framed this challenge through secondary research."},{"type":"points","items":[{"title":"For the learner","body":"Show a clear prompt, offer physical answer choices and give predictable feedback, allowing for different response speeds and support needs."},{"title":"For the educator","body":"Understand attempts, time and support without having to write down every response while helping with the activity."},{"title":"Our direction","body":"Connect physical play to a simple phone interface, with a proposed record of how each answer was reached."}]},{"type":"paragraph","text":"We treated communication, emotion recognition and shape interaction as practice activities. The game is not a diagnostic or therapeutic assessment. Its intended learning value still needs evaluation beyond one visit."},{"type":"paragraph","text":"The questions and answer cards pair pictures with short English text. We therefore selected participants who could read independently for the field trial. Use by learners who cannot yet read remains untested."},{"type":"paragraph","text":"Final documentation: background and problem framing, pages 5–10; scope, page 26; participant selection, page 33."}]},{"title":"Ideation","body":[],"blocks":[{"type":"paragraph","text":"We explored three ways to answer physically: place an emotion token, arrange routine cards, or connect a situation with an emotion and response. We used SCAMPER, a set of prompts for changing an existing idea, to question the board, answer objects, feedback and progression while refining Giggles."},{"type":"heading","text":"1 · An emotion-token station"},{"type":"paragraph","text":"Present a short situation, then place the corresponding emotion token on a base. This direction explored a star light, a celebration after five stars and progression towards more complex emotions and responses."},{"type":"heading","text":"2 · Arrange an everyday routine"},{"type":"paragraph","text":"Place task cards in a sequence, receive feedback and rearrange them. The concept could grow from short routines to longer sequences and decisions about what should happen next."},{"type":"heading","text":"3 · Connect a situation, emotion and response"},{"type":"paragraph","text":"Read the Room explored scenario cards, emotion tokens and possible responses. Its proposed stars and levels belong to that alternative, rather than to the implemented Giggles firmware."},{"type":"table","caption":"SCAMPER explorations","headers":["Prompt","What we explored"],"rows":[["Substitute","Emotion tokens or physical shapes alongside RFID cards."],["Combine","Board movement and category-based learning activities."],["Adapt","Everyday situations: help, sharing, apologies and boundaries."],["Modify","Progress from recognition to more complex situation-based questions."],["Put to another use","Focused practice in one learning category."],["Eliminate","Unnecessary digital controls in the learner’s interaction."],["Reverse","Start from an emotion or response, then identify the situation."]]},{"type":"paragraph","text":"The alternatives separated three kinds of practice: recognising an emotion, ordering a routine and choosing a response to a situation. Giggles brought communication, emotion and shape activities into one board. That meant the questions could change while players kept the same turn sequence and physical-answer rule."}]},{"title":"How to play","body":[],"blocks":[{"type":"paragraph","text":"The phone presents the question, but the answer happens on the board. For Communication and Emotion, the player chooses a card and taps it on the reader. For Shapes, the player presses a matching physical shape. This keeps the same question-and-answer sequence across the three activities."},{"type":"points","items":[{"title":"Tap a card","body":"For Communication and Emotion questions, the reader identifies the card and the controller checks it against the expected answer."},{"title":"Press a shape","body":"A Shape question enables the physical buttons and ignores unrelated RFID answers."},{"title":"Read or hear the prompt","body":"The landscape phone displays the question, active turn and feedback; answers belong on the reader or shape controls."}]},{"type":"paragraph","text":"Testing showed that this split was not always clear: participants tried to answer on the phone screen. We proposed reader lights, an arrow and spoken guidance to make the answer location easier to find."}]},{"title":"Activities and questions","body":[],"blocks":[{"type":"paragraph","text":"The documented bank contains six prompts per category. Four Communication cards and four Emotion cards can answer several situations; each question also has a stored hint. These are the defined activity responses, not recorded participant results."},{"type":"table","caption":"Communication · Six prompts","headers":["Prompt","Expected card","Hint after the second wrong answer"],"rows":[["Someone keeps taking your pencil.","Please stop.","How would you stop someone?"],["You cannot open your lunch box.","Can you help me?","Ask for help"],["A friend gives you a gift.","Thank you!","What do you say when someone gives you something?"],["You accidentally break your friend’s toy.","I’m sorry.","What do you say when you make a mistake?"],["Your teacher gives you a sticker.","Thank you!","What do you say when someone gives you something?"],["You cannot tie your shoelaces.","Can you help me?","Ask for help"]]},{"type":"table","caption":"Emotion · Six prompts","headers":["Prompt","Expected card","Hint after the second wrong answer"],"rows":[["Child is smiling and laughing.","Happy","Their face shows joy."],["Child is crying.","Sad","They look upset."],["Child is shouting.","Angry","Their face shows anger."],["Child is playing with balloons.","Happy","Their face shows joy."],["Child lost their toy.","Sad","They look upset."],["Child is lost in a crowded place.","Scared","They feel afraid."]]},{"type":"paragraph","text":"Emotion matches are simplified expectations inside the game. They are not universal rules about how someone must feel, and matching a card does not demonstrate real-world emotional understanding."},{"type":"table","caption":"Shapes · Six documented prompts","headers":["Displayed object","Expected shape","Stored hint"],"rows":[["Ball","Circle","The shape has no corners."],["Window","Square","The shape has 4 equal sides."],["Pizza slice","Triangle","The shape has 3 sides."],["Clock face","Circle","The shape has no corners."],["Square photo frame","Square","The shape has 4 equal sides."],["Star cookie","Star","It has 5 pointy corners."]]},{"type":"paragraph","text":"The full question bank contains Triangle and Star prompts, while the final firmware implements Circle and Square answer controls. The documentation does not identify whether those unsupported prompts were excluded from the active build. The tables show the intended content, not proof that all six Shape prompts were playable. Before another session, the active question list must be matched to its physical answers; completing the physical shape set remains future development."}]},{"title":"Feedback","body":[],"blocks":[{"type":"paragraph","text":"I programmed three levels of support: Try Again, a question-specific hint, then the answer. The same question stays active until the player gives the correct physical response, even after the answer is shown. This lets the player finish the action instead of being moved on immediately after a mistake."},{"type":"table","caption":"Feedback and turn progression","headers":["Event","What happens"],"rows":[["First wrong answer","Red feedback and Try Again; keep the question active."],["Second wrong answer","Give the stored question-specific hint."],["Third and later wrong answers","Reveal the answer; still wait for the correct physical response."],["Correct before reveal","Green feedback, positive speech and a score increment, then advance the turn."],["Correct after reveal","Give positive feedback and advance, without the same pre-reveal point."]]},{"type":"paragraph","text":"The third wrong response does not force a new question. The child still supplies the correct card or implemented shape press before the next turn. A pre-reveal score can follow a hint, so it is not a measure of first-attempt correctness."}]},{"title":"Electronics and logic","body":[],"blocks":[{"type":"paragraph","text":"I used an ESP32, a small programmable controller, to connect the card reader, sensors, shape buttons, feedback lights and phone interface. The RC522 reader identifies each RFID card. The phone connects over local Wi-Fi, so the working game does not need a separate computer or cloud server."},{"type":"heading","text":"Physical event → game state → feedback"},{"type":"points","items":[{"title":"Read the input","body":"A category sensor, RFID card or shape control supplies the physical event."},{"title":"Apply the rules","body":"The ESP32 chooses the question, checks the answer and coordinates feedback and turns."},{"title":"Present the state","body":"The phone reads the current game data from /state, updates the screen and speaks the prompt or feedback."}]},{"type":"paragraph","text":"This split gives each part one job: the controller decides which answers and inputs are valid, while the phone presents the current state. For example, a Shape question accepts a physical shape press and ignores an RFID answer; the replay card is accepted only after the whole game ends."},{"type":"heading","text":"Build and integrate"},{"type":"paragraph","text":"We tested controller inputs separately, verified RFID identifiers and LED responses, then connected the interaction logic to the phone. This helped separate electrical, firmware and browser faults. The main loop keeps input handling, delayed advance, finish handling and web requests in separate functions."},{"type":"heading","text":"The components and their roles"},{"type":"paragraph","text":"Reference photographs identify component families; the original build photographs document our assembly."},{"type":"table","caption":"Prototype components","headers":["Component","Role"],"rows":[["ESP32 development board","Runs the game rules, reads inputs and serves the phone interface over local Wi-Fi."],["MFRC522 / RC522","Reads START, answer and replay cards over SPI."],["Touch-sensor inputs","Three category inputs and a Finish input."],["Circle and Square controls","Implemented physical Shape answers."],["Red and green LEDs","Main feedback and dedicated shape feedback."],["RFID cards","Physical answers plus start/replay controls."],["Landscape phone/browser","Displays the active question and feedback, with speech output."],["LittleFS","Stores images served locally by the ESP32."]]},{"type":"paragraph","text":"I wrote the controller program in Arduino C++, using WiFi, WebServer, SPI, MFRC522 and LittleFS. SPI is the connection to the card reader; LittleFS stores the images on the controller. The phone reads JSON game data from /state and images from /img/. The controller checks answers and turns; the browser displays and speaks the result."},{"type":"table","caption":"Five states keep inputs in context","headers":["State","Purpose"],"rows":[["GAME_NOT_STARTED","Wait for the START card."],["WAITING_FOR_MOVE","Wait for the active player’s category or finish input."],["QUESTION_ACTIVE","Enable the appropriate physical answer input."],["PLAYER_FINISH_SCREEN","Show individual completion for five seconds."],["GAME_FINISHED","Show final completion and accept the replay card."]]},{"type":"paragraph","text":"The report describes six questions per category with separate used-question tracking: select from the available pool and reset after all six are used. It does not provide a versioned active question list to reconcile the six Shape prompts with the two implemented controls. The firmware cycles through three players. It does not establish automated dice reading or separate pawn detection on all 18 learning blocks."},{"type":"table","caption":"Recorded final GPIO map","headers":["Subsystem","Signal","GPIO"],"rows":[["Board input","Communication","2"],["Board input","Emotion","27"],["Board input","Shape","33"],["Board input","Finish","12"],["RC522","SDA / SS","5"],["RC522","RST","22"],["RC522 SPI","SCK","18"],["RC522 SPI","MISO","19"],["RC522 SPI","MOSI","23"],["Main feedback","Green LED","13"],["Main feedback","Red LED","14"],["Shape input","Square","25"],["Shape input","Circle","21"],["Square feedback","Green LED","15"],["Square feedback","Red LED","26"],["Circle feedback","Green LED","4"],["Circle feedback","Red LED","32"]]},{"type":"paragraph","text":"Shape buttons use internal pull-ups and read LOW when pressed; category and finish inputs are active HIGH. The circuit shares a common ground. Debounce timers reduce repeated input counts, although the field trial exposed a different problem: intentional finger-counting could trigger a category before the pawn arrived."},{"type":"paragraph","text":"Replay is accepted only at final completion. The card clears in-session data and returns to Start; it is ignored during normal play so a stray tap cannot restart the session."},{"type":"paragraph","text":"Final documentation, pages 26–32. Its functional checklist has blank result cells; the checklist is not a completed pass report."}]},{"title":"Teacher app concept","body":[],"blocks":[{"type":"paragraph","text":"The proposed Teacher App would let an educator set up a session and review a child’s attempts, support needs and history. Teammates designed these interfaces; I helped review and direct them. The app was not connected during the trial, and the names, percentages, times and trends shown here are sample data."},{"type":"heading","text":"Set up a session"},{"type":"heading","text":"Review a child and their sessions"},{"type":"table","caption":"Proposed session data","headers":["Record","What it would explain"],"rows":[["Final result","Correct response or answer revealed."],["First-attempt correctness","Whether the initial response was correct."],["Attempts","Responses made before completion."],["Hint usage","Whether additional support was needed."],["Response time","Timing in context, rather than a stand-alone ability score."],["Category","The area practised."],["Timestamp and question ID","When and which question was answered."],["Session history","How a child’s own sessions relate over time."]]},{"type":"heading","text":"Summarise and share"},{"type":"paragraph","text":"The proposed AI layer would turn recorded gameplay into a plain-language, non-clinical summary for educators, parents or therapists. It depends on saving real session records first. The current screens use sample data; the prototype does not generate these reports."},{"type":"table","caption":"Working prototype and wider design","headers":["Area","Working electronics","Further development"],"rows":[["Board and turns","Three category inputs, Finish and a three-player cycle.","Refined construction and complete embedded sensing."],["Answers","RFID answers; Circle and Square controls.","Complete Triangle and Star interactions and editable content."],["Child display","Locally hosted browser interface.","Connect the interface to a complete session system."],["Records","Current state and scores in ESP32 memory.","Persistent individual records across sessions."],["Teacher app","Not connected to the final electronics.","Setup, live monitoring, history and reports."],["Analytics and AI","Not persisted or implemented end to end.","Contextual progress views, summaries and reports from real records."]]},{"type":"paragraph","text":"Compare each child primarily with their own history. Response speed, retries and hints need an educator’s context; they should not diagnose, rank or define a child’s ability."}]},{"title":"Field testing","body":[],"blocks":[{"type":"paragraph","text":"We tested Giggles with four participants at Vishwansh Foundation, Pune: one adult aged 24 individually, and three children aged 8–10 in a group game. We first explained the board, cards, shape buttons and a complete turn to the teachers. They then introduced and supported play using their familiar classroom approach."},{"type":"table","caption":"Four participants, two session formats","headers":["Format","Participants","Age","Support"],"rows":[["Individual session","1 adult","24 years","One-to-one play with teacher support."],["Group session","3 children","8–10 years","A full three-player game facilitated by teachers."]]},{"type":"paragraph","text":"Participants were selected because they could read independently. Each participant played one session during a single visit, with teachers introducing and supporting both formats."},{"type":"heading","text":"Use the classroom’s existing routines"},{"type":"paragraph","text":"Before play, the teacher wrote each player’s pawn colour on the whiteboard. This reused the class’s familiar place for instructions and reminders, giving players a visible reference for their pawn. Teachers supported the first one or two attempts as participants learned where to tap, press and choose."},{"type":"table","caption":"What happened during play","headers":["Documented situation","Support or system response","What it means for the next build"],"rows":[["Children read questions and options aloud, chose a card and tapped the reader.","Teachers guided reading and the first one or two attempts. LEDs, audio and the phone responded to physical answers.","Preserve the physical answer and feedback loop; add a practice turn and reader cues so instructions arrive before the action."],["Three players needed to see a screen facing one side.","The board had to be rotated each turn so the next child could see it.","Try a shared-screen arrangement. Check visibility from each seat without moving the board."],["Children forgot their pawn or counted from Start; counting fingers also activated questions early.","The whiteboard kept pawn colours visible, but did not resolve turn and counting confusion. Touch sensors could respond before the pawn arrived.","Repeat player colour at the point of play and distinguish counting from arrival before recording question timing."]]},{"type":"paragraph","text":"These are summaries from the final report, not reconstructed individual session logs. Matching and pressing the shapes was reported as particularly engaging. Teacher guidance is part of this evidence: a completed answer does not establish that it was independent."},{"type":"paragraph","text":"Final documentation: session setup and observations, pages 33–35; evidence limits, page 41. No structured task-success rate or longitudinal learning measure is reported."}]},{"title":"Pain points and proposals","body":[],"blocks":[{"type":"paragraph","text":"The sessions revealed eight pain points, from learning the rules to seeing the shared screen and triggering questions too early. Each observation below is paired with a proposed change for the next version. These changes have not been implemented and retested in the documented work."},{"type":"comparison","before":"Children needed help during the first one or two attempts: where to tap, which shape to press and which card to choose. Once the flow became familiar, they enjoyed playing.","after":"Guide the next action at the board with a glowing reader zone, lit shape controls and an on-screen picture of what to use."},{"type":"comparison","before":"Without a practice round, children had to learn the rules and play at the same time, which caused confusion.","after":"Add a short demonstration round that walks through one practice turn with audio before the real game begins."},{"type":"comparison","before":"Emotion and situation cards were confused when the decks sat beside one another.","after":"Give each category a consistent colour and symbol across card, tray and screen, such as a speech bubble for situations and a face for emotions."},{"type":"comparison","before":"The prototype had no Hindi or Marathi option for either the on-screen text or spoken prompts.","after":"Add Hindi and Marathi text and audio, with a per-child language choice in the proposed Teacher App."},{"type":"comparison","before":"With three players around the board, the screen faced one side. The board had to be rotated each turn so the next child could see it.","after":"Explore a raised, rotating screen stand in the centre, or mirrored displays that every player can see."},{"type":"comparison","before":"Children forgot which pawn was theirs and sometimes counted from Start instead of their current position.","after":"Repeat each player’s pawn colour on screen and illuminate the occupied block as the starting point for counting."},{"type":"comparison","before":"Children tried to touch the phone screen to answer instead of tapping their card on the RFID reader.","after":"Point to the reader with an on-screen arrow, a spoken “Tap your card here” cue and a light on the reader itself."},{"type":"comparison","before":"Touching blocks while counting activated a question before the pawn reached its destination.","after":"Explore detection that responds only to the pawn, such as a magnet or tag, or show the counting hops on screen."},{"type":"paragraph","text":"Final documentation: eight pain-point cards on pages 37–38, introduced as proposed next-round fixes on page 36."}]},{"title":"What worked","body":[],"blocks":[{"type":"paragraph","text":"The documentation identifies ten strengths to retain. These combine observed reactions with useful design qualities; they are not ten measured learning outcomes."},{"type":"points","items":[{"title":"One question at a time","body":"Each screen keeps one picture and one question in focus."},{"title":"A consistent layout","body":"Communication, Emotion and Shape questions use the same screen structure, so the next prompt has a familiar place."},{"title":"Support before completion","body":"Try Again, then a hint and answer reveal, keeps another attempt available instead of ending the turn with a punitive message."},{"title":"An answer they can hold or press","body":"Physical cards and buttons turn the response into a tap or press rather than another screen control."},{"title":"Audio alongside the question","body":"A speaker option reads the question aloud. The documented participants could read independently; use by non-readers was not tested."},{"title":"A calm visual base","body":"Cream backgrounds, rounded forms and soft colour are design choices to retain while refining the interaction."},{"title":"A familiar educator nearby","body":"Teachers introduced and supported play in their familiar classroom manner. Connected app monitoring remains a future feature."},{"title":"Familiar situations","body":"Lunch boxes, shoelaces, gifts and sharing gave communication questions an everyday context."},{"title":"Shapes invited a physical response","body":"Finding and pressing the matching shape was a particularly engaging part of the session."},{"title":"Requests to play again","body":"The documentation records children asking for another round after the game ended—a qualitative sign of interest."}]},{"type":"paragraph","text":"The useful pattern was engagement after teacher guidance, especially around physical responses, with requests to play again. We would preserve those parts while making the first turns clearer. These observations do not establish gains in reading, motor skills, real-world transfer or retention."},{"type":"paragraph","text":"Final documentation: six strengths on page 40 and four continuing at the top of page 41."}]},{"title":"Next steps","body":[],"blocks":[{"type":"paragraph","text":"I would fix the instructions, shared-screen visibility and premature sensor activation before adding more metrics. If a question starts while a child is still counting, its timing and attempts would be hard to interpret. The next build should make the intended turn reliable, then be retested over several sessions before connecting saved records and the Teacher App."},{"type":"table","caption":"A proposed build order for the eight findings","headers":["Priority and findings","Next design or build decision","What to observe after the change"],"rows":[["1 · Counting fingers trigger questions early.","Compare pawn-only detection with an explicit arrival action. First reconcile active Shape prompts with the controls actually available; neither fix is complete.","Count and move a pawn without starting a question early; then finish the intended answer and next turn. Check every active Shape prompt has a valid physical response."],["2 · First-use guidance, missing practice round, mixed card decks and touchscreen expectations.","Build one practice turn, consistent category symbols and a visible reader cue. Keep the answer on the board while making that location clear on screen.","Where does the learner try to answer? Record the teacher’s prompt, the learner’s action and the game response, including help still needed."],["3 · Shared-screen visibility and pawn/counting confusion.","Compare a central rotating stand with mirrored displays; repeat pawn colour and current position near the turn. These remain alternatives to try, not a selected tested solution.","Can each player see the prompt and start counting from the current position without rotating the whole board?"],["4 · English-only text and audio.","Review the prompts and hints with educators before adding Hindi and Marathi. Define text, speech and support needs together, then test the chosen language flow.","Can the intended learner understand the instruction and answer options with their usual support? Keep outside help distinct from software hints."]]},{"type":"points","items":[{"title":"Test the next build over time","body":"Run another round with more participants and several sessions. Record support, attempts, response time, hint use and sensor behaviour, while keeping teacher facilitation visible in the evidence."},{"title":"Then connect the educator system","body":"Persist a real session record before extending the dashboard or AI summaries. Review with educators whether attempts, hints and separately recorded teacher help explain the answer; do not treat a pre-reveal score as independent success."}]},{"type":"heading","text":"What this visit can support"},{"type":"paragraph","text":"Four participants and one visit give us issues to investigate, rather than evidence of a lasting learning benefit. Teachers helped participants, and early hardware caused some breakdowns. We have not measured learning, retention, changes in engagement over time or the effect of the proposed fixes."},{"type":"paragraph","text":"The next version should keep one question at a time, a consistent layout, supportive feedback, audio and tangible shape interaction. The aim is to reduce avoidable setup and turn friction without removing the teacher’s role."}]},{"title":"Meraki and reflection","body":[],"blocks":[{"type":"paragraph","text":"Giggles received Best Project at Meraki, our pre-grad show. My main contribution was connecting the physical inputs, game rules and phone feedback into a working prototype. The classroom trial then showed what that working system still needed: clearer instructions and better support for shared play."},{"type":"points","items":[{"title":"An input needs the right meaning","body":"Debouncing filters repeated electrical signals. It does not distinguish a counting finger from a pawn. That requires a different sensing decision, not just another timer."},{"title":"Physical controls still need guidance","body":"A functioning reader or button is not enough if a player expects a touchscreen or mixes the card decks. The next action needs to be clear where the player is looking."},{"title":"Shared play changes the requirements","body":"A phone that is readable from one seat is not equally visible to three players. Screen position, pawn colour and counting cues need to work around the whole board."}]},{"type":"paragraph","text":"Team: Anarghya YS, Mayuri Bhide, Payal Sajnani, Ruchi Tongaonkar and Lakshya Chopkar. Mentor: Asst. Prof. Aryan Halkude."}]}]},{"id":"workplace-mode","title":"Workplace Mode","contribution":"I handled the questionnaire, recruitment, interviews, analysis, concept and prototype. The academic paper has four co-authors. This continuation revisits the evidence and explores interaction alternatives.","duration":"Original study · November 2026 continuation","summary":"I studied how drivers experience in-car interfaces with a four-author academic team. In November 2026, I returned to one account: a song change lagged, and the driver kept checking. I built two ways to explain that response while keeping navigation available. The comparison is ready to try; driver evaluation is still ahead.","overview":[],"sections":[{"title":"Problem and scope","body":[],"blocks":[{"type":"paragraph","text":"One driver described difficulty switching between music and navigation. In a separate account, he described checking again when a song change lagged. I brought these accounts together into one question: how can the screen explain a delayed track change while keeping route information available?"},{"type":"paragraph","text":"Our paper compares 20 digitally confident drivers with 14 commercial drivers in Indian driving conditions. Their occupation, age and experience also differ, so digital familiarity alone cannot explain the differences between the groups."},{"type":"points","items":[{"title":"Original work","body":"A four-author academic study and an earlier Workplace Mode concept. Neither established that the proposed interface improved driving performance."},{"title":"Current continuation · November 2026","body":"Source review, secondary research, explicit synthesis, competing concepts and a desktop comparison prototype. Framework outputs below were created during this continuation."},{"title":"What the project can deliver now","body":"A traceable interaction hypothesis and a testable prototype. Vehicle signals, provider integration and real driving benefits remain outside the demonstrated work."}]}]},{"title":"User research","body":[],"blocks":[{"type":"paragraph","text":"We used two adapted questionnaires with agreement ratings, categorical questions and open responses. Our paper records 34 survey responses. The earlier project handoff separately records 13 interviews; the overlap between those groups is unknown. I keep those method counts separate rather than reporting 47 participants."},{"type":"table","caption":"What each research record establishes","headers":["Record","Known base","Use and boundary"],"rows":[["Academic paper · pp.8–14","34 survey responses: 20 digitally confident and 14 commercial drivers","Reported experience and broad themes; group differences also involve occupation, age and experience."],["Earlier interview handoff","13 interviews: six private and seven commercial drivers","Collection context and surviving accounts. Overlap with survey respondents is unknown; these are not 47 unique participants."],["GD02 task account","One private driver; related accounts, not one verified combined episode","Reason to investigate delay and switching, not a task-frequency ranking or a commercial-driver result."]]},{"type":"heading","text":"Questionnaires, collection and interpretation limits"},{"type":"paragraph","text":"The digital-comfort topics include smartphone-use frequency, exploring unfamiliar features and connecting unfamiliar devices. The private-driver instrument describes six stress/context items, four interaction-friction items and three safety/preference items. These topics make the questionnaire inspectable; the paper does not fully specify a validated literacy measure or the thresholds used to classify drivers. (Paper pp.9–10.)"},{"type":"table","caption":"How collection affects interpretation","headers":["Source detail","What it means for this case"],"rows":[["Private-driver form · English, online","Digital comfort and interface experience are self-reported; no objective literacy or attention test is established."],["Commercial-driver form · English/Hindi adaptation","Simplified functional wording helps contextual fit. Equivalent measurement across forms is not established merely by using the same response scale."],["Thematic analysis · paper pp.11–18","The report describes a six-phase process and four core themes. The original affinity board uses seven clusters. These are different documented groupings; their exact coding relationship is not recorded."],["Numerical summaries","Several chart/prose values and percentage denominators need reconciliation with raw responses. They are not used here as precise effect sizes or concept-selection scores."]]},{"type":"paragraph","text":"The earlier handoff describes private-driver interviews by video and commercial-driver conversations around refuelling queues, with questions read aloud in Hindi or English where needed. These collection details come from that record, rather than being inferred from the paper. Different settings and administration modes matter when interpreting group differences."},{"type":"paragraph","text":"The study is small, cross-sectional and largely self-reported. It offers useful accounts of difficulty; it does not provide eye-tracking results, crash outcomes or a test of these concept screens. The paper’s “representative quotes” lack stable participant identifiers, so they are not reproduced here as verified verbatim interviews."}]},{"title":"Research findings","body":[],"blocks":[{"type":"paragraph","text":"The report groups the findings into context-related stress, interaction depth, physical or visual displacement, and a preference for useful simplicity. A lower reported error count can coexist with avoiding the screen. That makes “more completed tasks” an incomplete definition of success."},{"type":"table","caption":"Reported pattern → interpretation to investigate","headers":["Reported in the paper","Interpretation and boundary"],"rows":[["Menu steps and switching · pp.17–18","Task structure may create unnecessary search. The exact task and existing shortest route still need inspection."],["Freezing, lag or unexpected responses · pp.14, 19","Feedback uncertainty is one possible mechanism. Network delay, a frozen display and a wrong action need different remedies."],["Leaning or reaching · pp.18, 25","The seat, display and target arrangement matter. A desktop screen cannot establish a physical reach improvement."],["Avoiding interaction · p.24","Leaving the screen alone can be an adaptive response. It must not automatically be counted as failure."]]},{"type":"paragraph","text":"Preferences also resist a single answer. The paper reports mixed responses to physical controls and voice, rather than a universal replacement for touch. The redesign therefore starts from a specific task, not a rule that one modality suits everyone."}]},{"title":"Secondary research","body":[],"blocks":[{"type":"paragraph","text":"I used published research to challenge my design: keep existing shortcuts, let people leave optional work, and explain what is actually known. These sources changed the comparison requirements; their participants are separate from our study."},{"type":"table","caption":"External evidence → design consequence","headers":["Finding and source","Decision for this project"],"rows":[["Interrupted tasks should retain input and make resumption understandable · NHTSA [1]","Use a state-preserving baseline. Adding a Resume button is not sufficient differentiation."],["Preference, time and interaction demand can diverge · Cooper et al. [2]","Evaluate understanding, errors and effort separately. Voice is not automatically low demand, and easier use may encourage more engagement."],["Menu effects depend on the task · Louveton et al. [3]","Compare a matched task with its required information. Fewer taps alone do not establish a better or safer interaction."],["Resumption uses task context · Villing [4]","Investigate the smallest useful reminder. The eight-person dialogue study did not validate an automated return feature."],["Driver-paced interaction and retained input · Transport Canada [5]","Allow leaving optional work. A deliberate no-return path remains valid."],["Platform constraints determine available behaviour · Google [6]","Keep an exit during waiting and distinguish reviewing a destination from applying a route change."],["Baleno variants use different equipment · NEXA [7]","Use Zeta’s 7-inch SmartPlay Pro as a provisional reference; do not mix Studio and Pro+ screens or claim the participant’s firmware is verified."],["Navigation and playback controls already coexist · Google [8]","Keep media widgets, recent-app access and supported steering controls. Test feedback meaning rather than removing competent shortcuts."],["System and app responsibilities differ · Google [9]","Treat the receipt as a system-level design exploration. Implementation needs the relevant platform owners and state interfaces, beyond a third-party media screen."]]},{"type":"paragraph","text":"These sources inform a new design direction. They do not establish that Workplace Mode reduces distraction, works for every Indian driver, or meets an automotive approval process."}]},{"title":"Design requirements","body":[],"blocks":[{"type":"paragraph","text":"I grouped the findings by the work they create: finding a function, understanding its response, reaching it, or deciding whether to continue. That gave me five requirements for the comparison below. This is new synthesis, not fresh coding of raw survey rows or one journey followed by every participant."},{"type":"table","caption":"Requirements that can fail a concept","headers":["ID / requirement","Acceptance question"],"rows":[["R1 · Predictable access","Does the comparison retain the shortest supported route and necessary context without adding another navigation detour?"],["R2 · Truthful state","Can someone distinguish a received command, pending response, confirmed playback and an unknown result?"],["R3 · Deliberate control","Can someone leave optional interaction without repeating a command or implying that an outstanding request was cancelled?"],["R4 · Continuity","Does the existing media widget or steering control already meet the task? Navigation and request state must survive changing views."],["R5 · Appropriate scope","Can the central benefit be demonstrated with desktop/Figma resources? Reach and driving-attention claims require different equipment."]]}]},{"title":"Why this task","body":[],"blocks":[{"type":"paragraph","text":"I chose music/navigation switching because GD02 described both frustrating switching and repeated checking after a delayed song change. I combined those related accounts into a test scenario. The notes do not establish that both happened in one episode, or that repeated checking meant repeated tapping."},{"type":"table","caption":"Task choice and boundaries","headers":["Evidence or decision","What changes in the prototype"],"rows":[["Primary task · change music and retain guidance","Use an unwanted-track change and a delayed response. Do not inflate this into playlist search or a reconstructed commercial ride incident."],["Current comparison context · existing Android Auto patterns","Keep widgets, recent-app access and steering controls. A real unit/version check is still needed before claiming a faithful product baseline."],["Provisional manufacturer reference · Baleno Zeta","The paper lists a 2024 Zeta; the current brochure identifies 7-inch SmartPlay Pro. That is a documentation choice, not proof of the participant’s installed firmware."],["Competing task · parked phone/projection setup","GD01’s Fronx account gives this a concrete basis. Investigate it if current playback controls already solve the primary task."]]},{"type":"paragraph","text":"The commercial affinity artifact mentions GPS and passenger-requested music, but it does not establish the same delayed-song episode. Transfer to commercial drivers needs follow-up. Reported difficulty also does not provide an objective task-by-task cognitive-load ranking."},{"type":"paragraph","text":"Maruti’s native shell, Android Auto’s projected interface and the playback app have different responsibilities. This is a system-level interaction exploration. Shipping it would require the relevant platform owners and reliable playback-state interfaces; a browser drawing is not an Android Auto extension API. [9]"},{"type":"heading","text":"What I need to learn before keeping the receipt"},{"type":"paragraph","text":"First I need to check the shortest ordinary route on an actual system. Steering controls, media widgets and audible playback may already resolve the task. The desktop comparison asks a narrower question: does the extra receipt help someone understand what is confirmed without adding unnecessary reading?"},{"type":"heading","text":"How I framed the question"},{"type":"paragraph","text":"When a music change responds slowly, what does the driver need to understand without losing navigation context? The six questions below narrow this investigation. The recorded account describes repeated checking; repeated tapping and the value of a new receipt remain questions to test."},{"type":"table","caption":"5W1H · new framing","headers":["Question","Working answer"],"rows":[["Who?","Drivers with different tasks and digital familiarity. Do not infer an individual’s ability from their occupation."],["What?","Changing an unwanted track, understanding the response and retaining or returning to guidance. This combined task is a new synthesis of related accounts."],["When?","Around a delayed playback response or a view change. Optional audio interaction can be left alone."],["Where?","A desktop model informed by existing Android Auto patterns; provisional Maruti reference: Baleno Zeta, 7-inch SmartPlay Pro. Exact participant firmware remains unverified."],["Why?","Reduce avoidable search and misunderstanding while preserving the choice not to engage."],["How?","Compare ordinary clear feedback with an explicit action receipt, using the same task, controls and simulated response states."]]},{"type":"heading","text":"Five Whys: follow different explanations"},{"type":"paragraph","text":"The recorded song-change account supports examining response clarity. It does not establish the cause of the lag or prove that more status text will help. The candidate must improve understanding beyond the existing controls without adding another task."},{"type":"heading","text":"Task goals and opportunity hypotheses"},{"type":"paragraph","text":"The current analysis focuses on two goals: find a familiar control without unnecessary searching, and understand an action well enough to wait, leave or return. These task stories guide the design; they are not participant quotes or the results of new interviews."},{"type":"points","items":[{"title":"Find the control","body":"When I need a familiar adjustment, I want a predictable route to it so I can avoid searching across unrelated functions."},{"title":"Understand and leave an action","body":"When an action does not respond as expected, I want to understand what happened and whether anything still needs my input, so I can wait, leave it or return deliberately."}]},{"type":"table","caption":"Proposed task breakdown","headers":["Goal / plan","Question the baseline must answer"],"rows":[["0 · Resolve or leave a secondary task","Is this task necessary now, postponable or unnecessary?"],["1 · Find the function","Which steps are genuinely required and which are navigation detours?"],["2 · Request a track change","Was the command captured locally, and what playback response is still outstanding?"],["3 · Understand the result","What is confirmed, failed or unknown? Last confirmed playback may be stale."],["4 · Leave or return","Does navigation remain available? Returning must not repeat the relative Next command."]]},{"type":"paragraph","text":"This is a proposed goal model with conditional plans, not an observed click path. The opportunity map follows three distinct branches: remove unnecessary search; make known and unknown state understandable; preserve useful context. Physical reach remains a separate investigation because a desktop preference test cannot settle it."}]},{"title":"Concept alternatives","body":[],"blocks":[{"type":"paragraph","text":"The earlier proposal combined a commercial work layer with inferred driving states and request holding. The continuation separates those dependencies and explores eight alternatives. They are new proposals, not directions all generated or tested during the original study."},{"type":"table","caption":"Candidate comparison · desktop-only scope","headers":["Direction / intended value","Main weakness / current disposition"],"rows":[["Departure Plan · optional preparation before a trip","Existing setup flows already cover much of this. Keep only if a specific preparation failure is found."],["Return Point · resume a local draft deliberately","Ordinary persistence may already solve it. Investigate only against a competent baseline; no automatic replay."],["Reach Fit · a stable, physically suitable control arrangement","Strong link to reported reaching, but physical benefit needs a seat/display setup. Defer that claim."],["Phone Handover · explicit ownership during a device change","Needs an actual handover conflict and supported platform behaviour. Do not assume either."],["Decision-Cost Routes · preview route demands before setting off","Local data quality and established route features limit differentiation. No “safer route” score."],["Passenger Task Pass · bounded assistance for optional tasks","Assistance and permission needs require their own evidence. No access to critical controls."],["Car Familiarity Check · optional model-specific rehearsal","Could transfer burden to the driver instead of fixing the interface. Needs a verified unfamiliar-car problem."],["Repair Replay · review supported technical events after a drive","Useful only with real event capture and a service recipient. A report receipt is not a diagnosis or fix."]]},{"type":"paragraph","text":"We set the comparison criteria before choosing a direction: support from the evidence, practical value, feasibility, failure handling, differentiation and what we could test. An option must show the true status and leave the decision to the user, whatever its overall score."},{"type":"paragraph","text":"Return Point ranked highest in an earlier broad concept review. The later task trace changed the direction: a delayed song change has a specific source account, while lost destination drafts do not. The current proposal therefore investigates playback-response clarity. The earlier ranking is not a result for this new design."}]},{"title":"Comparison prototype","body":[],"blocks":[{"type":"paragraph","text":"The new desktop prototype compares two feedback approaches for the same music/navigation task. Both retain navigation context, media shortcuts and simulated steering controls. The proposed action receipt separates a captured command from a confirmed playback change, with no extra approval step for a normal track skip."},{"type":"heading","text":"Compare the same delayed track change"},{"type":"paragraph","text":"Start both approaches on City morning, request Next toward Open coast, and choose the delayed response. Both keep the route, controls and last-confirmed track. Neither can call Open coast confirmed while the request is pending."},{"type":"table","caption":"Same condition, different explanation · current desktop model","headers":["Approach","What stays the same","What to inspect"],"rows":[["A · Existing-pattern comparison","City morning remains last confirmed; the same Next request is pending and the same route stays available.","Ordinary pending feedback already explains that playback has not confirmed the change. This is a competent comparison, not an interface made silent to lose."],["B · Explicit action receipt","The same request, service response, controls and route context.","An added receipt separates input received locally from playback confirmation. It must earn its extra reading by improving understanding."]]},{"type":"paragraph","text":"Switch both to an unknown outcome to inspect the harder case: the last-known track may be stale. Reading the current playback state must request information, not send Next again. These are annotated model states to try, not driver findings or OEM screenshots."},{"type":"list","items":["Open the audio/navigation prototype. Compare both feedback approaches and the researcher-controlled response states. Track names and route drawing are illustrative; no audio, live navigation or vehicle is connected."]},{"type":"table","caption":"What each alternative must demonstrate","headers":["Approach","Keep it only if…"],"rows":[["A · Existing-pattern comparison","The best existing routes remain available, with ordinary clear pending, failure and unknown feedback. Do not hide shortcuts or silence all feedback to make it lose."],["B · Explicit action receipt","People understand the command and result more accurately without extra reading, extra controls or an unwanted action when returning."]]},{"type":"paragraph","text":"The simulation includes delayed, failed and unknown results. It models one relative track command at a time: returning or reloading cannot send another Next. Reading playback state requests information rather than repeating the action. Local mute changes the modeled output state; it does not cancel or confirm the track request."},{"type":"paragraph","text":"This is a silent model. In a real car, hearing the next song is also feedback. The first desktop evaluation can examine displayed-state understanding; it cannot establish how much the receipt changes real listening or repeated screen checking."},{"type":"paragraph","text":"The old Calm/Busy/Critical classifier and “held ride” story are not carried forward as validated behaviour. A screen cannot guarantee a provider reservation, infer a safe moment from its label, or repair a display process that cannot render."}]},{"title":"Failure and recovery","body":[],"blocks":[{"type":"paragraph","text":"A track change can be pending, fail or lose its response. Playback can also change elsewhere while the screen has old information. The following responses belong to a new design contract, not a completed automotive safety assessment."},{"type":"heading","text":"Test the assumptions that could invalidate the direction"},{"type":"paragraph","text":"First: does the current interface still leave the person uncertain? Second: can the relevant playback system expose truthful state? Third: does the receipt improve understanding beyond ordinary clear feedback? If those assumptions fail, revise or remove the extra receipt."},{"type":"table","caption":"Risk → design response → remaining check","headers":["Failure to examine","Proposed response / verification"],"rows":[["Last confirmed track mistaken for current playback","Qualify last-known information when a result is unknown. Ask what the person believes is playing and what the system actually knows."],["Local input mistaken for confirmed completion","Show pending separately from confirmed. Verify the system responsible for the result, not just a local tap animation."],["Response lost after an action","Show an unknown result. No automatic replay; require authoritative reconciliation before a consequential retry."],["A delayed response arrives after newer information","Match request identifiers and state versions. Do not let an old response silently replace a fresher authoritative state."],["Mute mistaken for cancelled Skip","Keep local output state and the outstanding playback request separate. Muting must not announce that a remote command was cancelled."],["Display cannot render or connection is unavailable","Do not imply that another label fixes the underlying failure. Declare which states are simulated and which capabilities are unavailable."],["The receipt increases reading or checking","Compare the same task with ordinary feedback. Reject the extra explanation if it creates more work without useful understanding."]]}]},{"title":"Results and testing plan","body":[],"blocks":[{"type":"paragraph","text":"I narrowed a broad work-layer idea to one source-backed task and built two functional feedback approaches. That is the completed design output; there are no new participant results yet. Drivers from the original study are available for follow-up, and I still need to arrange and conduct those sessions."},{"type":"paragraph","text":"A separate observation sheet now follows the same tasks, response conditions and approach labels. It records the person’s actual explanation, assistance and misunderstandings without treating a simulated response or a blank field as a result. The original Maruti decision and task choice are retained; exact participant firmware and a real baseline walkthrough remain unverified."},{"type":"list","items":["Open the driver-session observation sheet. Researcher tool · Blank, local-only records. Use the existing stationary protocol; no participant sessions have been conducted."]},{"type":"table","caption":"Planned formative evaluation · not conducted","headers":["Check","Method and decision"],"rows":[["Problem and baseline fit","Reconstruct a real recent task with an intended driver, inspect the actual product and record its existing shortcuts, persistence and failure states. Drop a concept whose problem is absent."],["Matched desktop tasks","Use the same unwanted track, navigation context, shortcuts and response conditions. Alternate A/B order; record familiarity, assistance and the actual participants."],["State comprehension","Ask what the system received, which playback state is confirmed and what remains unknown. Record critical misunderstandings before preference."],["Interruption and return","Use a declared stationary interruption. Check whether the person regains guidance and understands the outstanding request without it being sent again."],["Delay, failure and unknown","Inject each state explicitly. Check whether the person waits, leaves, cancels or repeats a consequential action. Do not infer system status from confidence alone."],["Progression beyond desktop","Only after useful formative findings: select actual hardware and an appropriate controlled study for reach, glance behaviour, workload and primary-task performance."]]},{"type":"paragraph","text":"Success would mean a meaningful improvement over the real baseline in the chosen task, with fewer critical misunderstandings and no added control burden. The acceptable difference and decision rules should be set before collecting comparison results, once the baseline and participant access are known. Faster completion alone is not evidence of safer driving."},{"type":"paragraph","text":"The change in direction is deliberate: a broad work layer became one source-backed task, and a destination-draft demo became a comparison of playback feedback. If the best existing controls already meet the need, the parked phone-connection problem remains a stronger next investigation than adding another layer."}]},{"title":"Sources","body":[],"blocks":[{"type":"paragraph","text":"Our primary study is Cognitive Load Across Automobile HMI Systems in Indian Driving Conditions, a 28-page academic paper by Ayushi Gupta, Lakshya Chopkar, Pranali Kasar and Vibha Shree MS. Study scope: pp.8–14; themes: pp.17–18; avoidance: p.24; limitations: pp.25–26. Publication and peer-review status are not established."},{"type":"paragraph","text":"Earlier project records: HMI_Case_Study_Handoff.md, MASTER_CONCEPT.md and the standalone Workplace Mode case, including its original affinity board. These preserve the earlier research and concept history; they do not establish that the November continuation was part of the original study."},{"type":"list","items":["[1] NHTSA · Visual–Manual Driver Distraction Guidelines (2013), Section V.J. Voluntary US guidance for original-equipment visual–manual secondary tasks. Interruptibility and retained input are established recommendations, not a novelty claim or Indian approval.","[2] Cooper et al. · Age-Related Differences in IVIS Demands (2020). Original on-road study, 125 participants and six vehicles. Voice preference, duration and demand were different questions. US context; age is not digital literacy.","[3] Louveton, McCall & Engel · Touchscreen Menu Depth, Breadth and Tasks. Inspected arXiv manuscript, 28 drivers in a simulator, four layouts and three tasks. Task-dependent effects; no universal menu optimum or verified journal-publication claim.","[4] Villing · Now, Where Was I? (2010). Eight-person human dialogue study, ACL pp.798–805. Informs resumption questions; did not test this prototype or an automated return card.","[5] Transport Canada · Visual Display Distraction Guidelines (2019). Official voluntary guidance on driver-paced tasks, feedback, interruption and resumption. Stopped in traffic still counts as driving; this is not a desktop compliance test.","[6] Google · Templated App Requirements. Platform requirements checked November 2026. Task exits, explicit route changes and scope-specific limits; not proof of a vehicle integration.","[7] NEXA · Baleno Variant Specifications. PDF page 8 identifies Zeta’s 7-inch SmartPlay Pro and steering audio controls. Current retrieved specifications do not establish the hardware or firmware in the participant’s 2024 car.","[8] Google · Android Auto System Widgets. Media controls and navigation context already exist. These capabilities inform a competent comparison, rather than a claim that another Next button is a new invention.","[9] Google · Media Design Responsibilities. Google and car makers control important parts of the media interface; media-app developers have bounded responsibilities. The desktop prototype is not permission or an API for changing Android Auto’s system UI."]},{"type":"paragraph","text":"The original study, external publications, new analytical diagrams and proposed evaluation are separate evidence layers. Secondary research supplies context and constraints; it does not add participants to our study or become a measured result for this prototype."}]}]},{"id":"jan-aushadhi","title":"Jan Aushadhi","contribution":"I helped guide research and concept discussions in our four-person team. We carried out the fieldwork, synthesis and concept development together.","duration":"2025 team project · November 2026 interface explorations","summary":"In 2025, our four-person team studied how patients and caregivers buy medicines. We developed three directions: a unified health card and app, a dispensing kiosk and RFID packaging. The report took the card/app further. The November 2026 continuation adds interface walkthroughs; the kiosk is a separate learning exercise, not a replacement for the selected concept.","overview":[],"sections":[{"title":"Problem statement","body":[],"blocks":[{"type":"paragraph","text":"Patients and caregivers paying for medicines need reliable information about their options and prices. Our research found that prescription confusion and uncertain stock made it harder to plan an affordable purchase and could mean another visit."},{"type":"paragraph","text":"We focused on this question: how could the service help people understand medicine options and prices, check availability and get support before they pay?"},{"type":"heading","text":"Notes behind stock and spending concerns"},{"type":"heading","text":"What the next service needs to address"},{"type":"points","items":[{"title":"Prescription confusion → a clear review","body":"Keep prescription, medicine and permitted quantity together so someone can check what they are collecting. Unclear information still needs pharmacy help."},{"title":"Stock uncertainty → verified availability","body":"Show a reliable stock result before payment and explain unavailable items. Checking before travel still needs a channel beyond the on-site kiosk."},{"title":"Help already matters → retain a handoff","body":"Keep staff help visible when someone cannot identify a medicine, sign in or complete collection. An unattended machine cannot replace that support."}]}]},{"title":"User research","body":[],"blocks":[{"type":"paragraph","text":"We visited Jan Aushadhi pharmacies and used observation, interviews and questionnaires to study medicine purchases. We included patients, caregivers and pharmacy teams, with questionnaires for users, non-users, pharmacy operators and doctors."},{"type":"heading","text":"What the retained research can establish"},{"type":"points","items":[{"title":"Mapped purchase accounts","body":"The contextual-inquiry models on report pages 14–17 show people, dependencies and purchase sequences. A caregiver account connects prescription-name confusion, price and contacting the pharmacy before travelling. These accounts explain a situation; they are not frequency estimates."},{"title":"Four questionnaire groups","body":"Pages 20–28 separate customers, non-users, Kendra operators and doctors. Recruitment details and a reliable response base for each chart could not be verified from the retained records. We do not turn their percentages into a participant total or combine them with the contextual accounts."},{"title":"Research synthesis","body":"The affinity map on page 29 groups reported stock, spending, awareness and trust concerns. We use those as research perceptions and design questions; comments about medicine quality are not clinical evidence."}]},{"type":"paragraph","text":"In one mapped caregiver purchase, matching prescription names to medicines required help, and the pharmacy was contacted by phone or WhatsApp to check availability and opening times. The stockout sequence then led to waiting, another store or human help. Those accounts connected information clarity, availability and staff support in our design question."},{"type":"paragraph","text":"We followed the purchase in context: how people understood the prescription, looked for medicine and handled a stockout. A Kendra is a Jan Aushadhi pharmacy."},{"type":"paragraph","text":"Our research brought together confusion about prescription names, uncertain stock, repeat visits and trust in the service. These findings describe the purchase experience; they do not measure the effect of a new kiosk."}]},{"title":"Service maps","body":[],"blocks":[{"type":"paragraph","text":"We mapped how patients and families depend on doctors, pharmacy staff and medicine suppliers. The maps show where information and responsibility pass between people, helping us identify what a kiosk alone could not solve."},{"type":"heading","text":"Who needs support, and who can act"},{"type":"paragraph","text":"We also compared who needs the service with who can help it operate. Patients and caregivers need clear choices; pharmacy staff, suppliers and other organisations would need to support stock information and fulfilment."}]},{"title":"Service concepts","body":[],"limitation":"The report contains proposed services and illustrative concept artwork. The later interface walkthroughs do not establish a deployed service or working dispensing hardware.","blocks":[{"type":"paragraph","text":"We generated fifteen early ideas and developed three directions: a unified health card and app, a dispensing kiosk, and RFID-enabled packaging. The report took the card/app direction further. The kiosk and packaging remain visible as explored alternatives, rather than being presented as rejected or proven inferior."},{"type":"points","items":[{"title":"Unified health card and app","body":"Selected for further development in the report."},{"title":"Medicine-dispensing kiosk","body":"Explored alternative; later interface-learning continuation."},{"title":"RFID-enabled medicine packaging","body":"Explored traceability concept."}]},{"type":"heading","text":"Why develop a shared card and app?"},{"type":"paragraph","text":"The report connects the selected direction to keeping prescriptions together, making medicine information accessible and checking availability before a visit (pages 47 and 57–58). This is the proposed mechanism behind the choice, not evidence that it performed better than the alternatives."},{"type":"points","items":[{"title":"Reach the decision before travel","body":"The mapped purchase already involved contacting the pharmacy for availability. An app or another remote channel could support that earlier step; a machine at the pharmacy cannot solve it on its own."},{"title":"Carry information between people","body":"The proposed card links a patient account to doctor and pharmacy interactions. The packaging concept instead identifies a package record. Those are different service roles, so one is not a direct replacement for the other."},{"title":"Accept the coordination cost","body":"The card/app depends on reliable records, current stock and participating staff. Its broader feature list does not remove those dependencies. The present walkthrough therefore concentrates on checking and requesting collection, with other functions left as proposed scope."}]},{"type":"heading","text":"See all fifteen brainstorming ideas"},{"type":"paragraph","text":"Complete idea inventory from report p.46. These are early team proposals, not delivered features or demonstrated medical capabilities."},{"type":"list","items":["Medicine Maker — composition-setting app for chronic conditions","DigiLocker for health needs","Jan Aushadhi branding rework","Composition teller","Subscription model","WhatsApp integration","Creating a database","Upload a prescription and order medicines","Medicine delivery","ATM-style medicine kiosk","Scheduled medicine purchasing","Medicine takeaway system","Check availability across Kendras","Quality-checker machine","Medicine arranger"]},{"type":"heading","text":"Unified health card and app"},{"type":"paragraph","text":"We proposed one route for keeping prescription information accessible, understanding medicine options and planning a collection. The report selected this direction and developed enrolment, doctor and pharmacy interactions. The next chapter shows its full proposed scope."},{"type":"heading","text":"Medicine-dispensing kiosk"},{"type":"paragraph","text":"We explored a machine beside a pharmacy to guide identification, prescription selection, stock checks, payment and collection. It would still depend on reliable stock, staff support and clear recovery when a purchase fails. Its illustrations are concept artwork, not hardware photographs."},{"type":"paragraph","text":"The earlier flow considered missing prescriptions, unavailable stock, permitted quantities, retry/cancel and receipts. A kiosk at the pharmacy cannot by itself answer the question of availability before someone travels. That still needs a separate information channel."},{"type":"heading","text":"RFID-enabled medicine packaging"},{"type":"paragraph","text":"We proposed a unique package identity linked to batch, expiry, billing and supporting quality records. The intended route was tagging, a recorded bill, and access through a shared link. The tag and the records behind it were not implemented; the illustration does not establish authenticity or medicine quality."},{"type":"list","items":["Inspect the fictional package-record example. New explanatory interaction · No tag reader or verified product record. It separates a record’s fields from evidence that a medicine is authentic."]},{"type":"paragraph","text":"The report records the selected direction and its intended benefits, but no formal comparative test or complete selection deliberation. The three directions remain part of the project. My later kiosk exercise is a separate learning choice, explained in its own chapter."}]},{"title":"Selected card and app","body":[],"blocks":[{"type":"paragraph","text":"We developed the unified health card and app further in the report. The card would identify the account; the app would bring prescription information, medicine details and collection planning together. These were proposed service functions, not a launched platform or measured improvement."},{"type":"list","items":["Try the new card/app collection walkthrough. New November 2026 AI-assisted interface exploration. Prepared fictional data and a local collection request, not live inventory, a medical record or a confirmed reservation."]},{"type":"heading","text":"Three connected journeys"},{"type":"points","items":[{"title":"Join with help","body":"A proposed registration centre checks documents and issues a physical or digital card. Consent and information requirements need review before real enrolment."},{"title":"Keep the prescription available","body":"The proposed doctor journey retrieves the permitted record and adds a prescription. It depends on consent, reliable records and staff access; no medical-record integration was built."},{"title":"Plan collection","body":"The proposed app checks medicine information and availability, then sends a collection request to the Kendra. The pharmacy prepares the order and helps with collection."}]},{"type":"heading","text":"Where the service still needs a person"},{"type":"points","items":[{"title":"An availability result needs an owner","body":"The source pharmacy flow assigns stock checking to the operator. A real pre-travel result would need someone responsible for its accuracy and freshness. The new walkthrough supplies fictional results; an unknown result routes to help."},{"title":"A request is not a reservation","body":"The walkthrough creates a local reference awaiting store review. Staff would need to agree who receives it, when they confirm it and whether stock is held before anyone travels. No request in this prototype contacts a pharmacy."},{"title":"The handoff must be completed","body":"The source flow places prescription review, stock checks and fulfilment with pharmacy staff. Passing a reference to the help screen only marks that dependency; it does not mean staff accepted the request or authorised collection."}]},{"type":"heading","text":"What the card and app were intended to contain"},{"type":"list","items":["Medicine information","Kendra location and contact details","Order-ahead collection","AI-assisted prescription reading and quantity suggestion","Medical history","Prescription hub","Lab-test repository","Insurance tracking","Card management","Permission-based third-party access","Expense tracking"]},{"type":"paragraph","text":"The source also proposes AI-assisted reading and quantity calculation. These functions were not implemented or evaluated. The new walkthrough uses prepared fictional items and fixed limits; it does not interpret a prescription or recommend a medicine."},{"type":"heading","text":"Inspect the original enrolment and service flows"},{"type":"paragraph","text":"The original enrolment order places biometric capture before consent. Page 51 also proposes up to ten years of medical history and approximately a month for card issue. These substantial first-use requirements need revision and staff review; this is a present design judgment, not a finding validated by this project. The current walkthrough starts with a prepared account and does not test enrolment."},{"type":"heading","text":"See all five original service storyboards"},{"type":"paragraph","text":"These are illustrative storyboards in the report, not field photographs, participant sessions or recordings of a working service. They show the proposed roles across the same card/app concept."},{"type":"list","items":["Doctor interaction · Report p.59","New user interaction · Report p.60","Existing user interaction · Report p.61","Kendra operator interaction · Report p.62","Local pharmacy operator interaction · Report p.63"]}]},{"title":"Kiosk learning exploration","body":[],"flow":{"label":"New interface simulation · November 2026","steps":[{"title":"Use the prepared account","body":"The lab models card/PIN entry with a demo action. It never asks for a real card or PIN. Someone without access can request staff help."},{"title":"Review the prepared items","body":"Choose fictional items within fixed limits and check the simulated stock result before payment."},{"title":"Review and simulate payment","body":"Edit quantities without losing the selection. Pending or unknown payment keeps the same reference while the result is checked."},{"title":"Collect or get help","body":"A confirmed result can lead to collection. Missing stock, uncertain payment or failed collection has a staff-supported route; no machine actually dispenses anything."}]},"limitation":"Identity, prescriptions, items, stock, payment and collection are simulated. No real financial transaction, medical recommendation, wallet service or dispensing is connected.","blocks":[{"type":"paragraph","text":"I chose a separate kiosk interface exercise because I had less experience designing for that format and wanted to broaden my design perspective. The new November 2026 AI-assisted prototype models a prepared account, prescription selection, stock review, simulated payment and collection or help. It is separate from our original team’s selected card/app concept."},{"type":"list","items":["Try the separate kiosk interface exploration. Later learning exercise · New AI-assisted November 2026 prototype. All identity, stock, payment and collection states are simulated; not evaluated with participants."]}]},{"title":"Results and next steps","body":[],"blocks":[{"type":"paragraph","text":"We produced field research, service maps and three concept directions, then developed the unified card/app further in our report. The later interface walkthroughs make a bounded part of the service reviewable. Next, pharmacy staff need to check the assumptions, followed by patient/caregiver sessions and revisions. No improvement in cost or waiting time has been measured."},{"type":"heading","text":"A lesson from the mapped purchase"},{"type":"paragraph","text":"The caregiver sequence already used phone or WhatsApp contact to check a pharmacy before travelling. That account gives the current continuation a concrete priority: make the stock result, request status and staff handoff understandable before adding more account or AI functions. This is a present design judgment grounded in that source account, not a newly observed improvement."},{"type":"points","items":[{"title":"Review the concepts with pharmacy staff","body":"Compare the card/app, kiosk and package-identity roles. Check stock ownership, staff handoffs, permitted collection and the reliability of each information source."},{"title":"Evaluate the selected journey","body":"Observe patients and caregivers using the prepared card/app collection task. Keep concept comprehension, interface usability and the separate kiosk learning tasks distinct."},{"title":"Operational evaluation","body":"A later pilot would need to examine stock accuracy, fulfilment, staff workload, purchase time and actual spending against a baseline."},{"title":"What I learned","body":"A cheaper medicine is only useful if someone can understand the options, find it in stock and get help when needed. Those service gaps need attention alongside the kiosk screen."}]},{"type":"heading","text":"See all fourteen future ideas from the report"},{"type":"paragraph","text":"Complete future-scope inventory, report p.64. Some entries extend earlier feature ideas. None is presented as a built integration, demonstrated health prediction or achieved benefit."},{"type":"list","items":["Store lab results","Connect wearable data","Medical-expense tracker","AI health prediction","Calories and macros from food photos","Support-group community","In-app video consultation","Consultation recording and automatic notes","Medicine subscriptions and refills","Public-health emergency alerts","Insurance comparison and claims portal","Medicine-demand prediction","ABHA integration","Alexa / Google Home medicine reminders"]}]}]},{"id":"tear","title":"TEAR","contribution":"I owned the concept, interaction, journey, art direction and design review. I directed ChatGPT-assisted brainstorming, logic development, implementation and narrative iteration, and selected external assets.","summary":"TEAR began as my final Immersive Media Design course submission. Feedback from one user gave me a reason to return to it. I continued the project through self-directed study and detailed one-to-one work with ChatGPT, developing a hand-opened dream journey where curiosity becomes wonder, fear and uncertain relief.","overview":[{"type":"heading","text":"The experience now"},{"type":"paragraph","text":"Current live desktop captures. The original course images and the feedback that prompted the redesign follow below."}],"sections":[{"title":"The course submission was the starting point","body":["TEAR began as my final submission for the Immersive Media Design course. The original idea was to make a change of world something the visitor could do with their hands: hold a seam, pull it apart and reveal another place. The first prototype established that interaction and a route through contrasting environments.","For the submission, I had to make the core idea understandable and demonstrable. I explored the opening, the places beyond it and how a visitor would continue. The early concepts below were preserved in my course documentation.","Completing the assignment did not answer the question that kept my interest: could opening a doorway become a moment of anticipation, rather than just a way to load the next scene? After submission, I chose to keep developing TEAR as a self-directed design exploration."]},{"title":"An original user session made the next questions clearer","body":["The original assignment records one user’s first-time desktop experience and headset feedback. A brief verbal explanation helped them begin on desktop. After the first tear, they could repeat the grip-and-pull idea across worlds. In the headset feedback, that gesture felt easy and the whale overhead stood out.","The same record exposed breaks in the experience: the room did not appear correctly at entry, and the two-palm help gesture was unreliable. The feedback also suggested improving the Forest sky and exploring atmospheric narration. These are paraphrased observations from that original individual session.","I took away two different tasks. Preserve the part that gave TEAR its identity—the physical opening and Ocean’s scale—and make the support around it easier to discover. Then investigate whether the environments and story could make the visitor care about what came next."],"points":[{"title":"Getting started needed a prompt","body":"I revisited entry guidance and made help something visible to find, rather than relying only on a remembered pose."},{"title":"The help gesture was unreliable","body":"The revised interaction uses a visible target activated with an index fingertip. It gives the visitor a location to aim at."},{"title":"The whale was memorable","body":"I kept Ocean’s upward attention and scale as a reference for the quality of presence I wanted elsewhere."}]},{"title":"From completing the brief to designing for presence","body":["After submission, I spent more time studying the project, revisiting references and thinking through what I wanted people to feel. I wanted the environments to hold attention at the visitor’s scale, the transitions to build curiosity, and the return to mean more than arriving back at the first scene.","The continuing work became a series of focused questions. What makes this patch of ground feel like a forest? Why does a mountain look placed into a scene rather than part of it? Is the voice describing the dream, or experiencing it? I used those questions to guide one-to-one brainstorming with ChatGPT.","I revisited the homepage as part of the same experience. Earlier layouts did not create the curiosity I wanted. I asked for motion and world previews, then removed a pull-to-reveal control that made the invitation feel unnecessarily complicated. The entry became more focused: glimpse the worlds, choose desktop preview or headset, then begin."],"points":[{"title":"Make the threshold matter","body":"The visitor sees another place before deciding to cross. Curiosity starts while still standing in the familiar world."},{"title":"Make each place belong to the story","body":"Ocean offers wonder, Shadow unsettles it, and Forest offers relief. The same opening carries a different emotional meaning in each place."},{"title":"Review from inside the experience","body":"Ground detail, movement, sound, captions and interruptions all matter when the visitor is surrounded by the scene."}]},{"title":"Directing ChatGPT through a concrete review loop","points":[{"title":"Grass: dense was not the same as natural","body":"I first asked for more coverage, then rejected a result that still looked artificial. The brief became varied height, more continuous ground cover, natural detail and brighter woodland light."},{"title":"Mountains: rough was not the same as believable","body":"A smoother mountain looked artificial; a sharper pass became too blocky. I kept asking for a more natural silhouette and lava that followed the land instead of reading as a straight line."},{"title":"Voice: horror was not the same as echo","body":"I rejected explanatory narration and robotic delivery. We moved to a first-person dream and compared fear directions before I selected the quieter performance: someone trying not to be heard."}],"flow":{"label":"The working pattern, repeated across the project","steps":[{"title":"Describe the experience I wanted","body":"Start with a feeling or friction: an alive forest, an unsettling sky, a doorway that invites a choice."},{"title":"Make the problem specific","body":"Use a screenshot, a reference or a small sample to identify what is not working. Keep the other worlds outside that revision."},{"title":"Explore and build a response","body":"Discuss options with ChatGPT, select a direction and translate it into something reviewable in the prototype."},{"title":"Inspect, reject or refine","body":"Compare the result with the intention. Accept what works, identify the remaining mismatch and set the next focused change."}]},"blocks":[{"type":"paragraph","text":"I used ChatGPT as a thinking and prototyping partner across concept development, reference research, interaction logic, environment refinement and narration. I supplied the intended feeling, screenshots, references and constraints. ChatGPT helped propose directions, reason through behavior and turn selected ideas into a working prototype. I reviewed the result and decided what needed to change."},{"type":"paragraph","text":"This was an ongoing dialogue, rather than one prompt followed by an accepted output. When a result missed the intention, I described the mismatch more precisely. I separated grass density from naturalness, mountain roughness from blockiness, and a frightened voice from a robotic voice with echo. Each distinction gave the next pass a clearer design question."},{"type":"paragraph","text":"For interaction logic, I worked through what should happen when the visitor holds, releases, crosses or returns. For the story, I compared alternatives and listened to delivery options. The value of the AI-assisted process was making these ideas concrete enough to inspect and challenge; design judgment still required looking at the experience again."},{"type":"comparison","before":"“the change is very minimal”","after":"The ground sample needed to be identifiable before I could judge it. I asked to mark the area, review the detail at that scale, and keep refining density and naturalness before extending it.","note":"Short verbatim excerpt from my development conversation; the decision summary is paraphrased."},{"type":"heading","text":"Review artifact: the temporary 5 × 5 metre marker"}]},{"title":"A doorway you could choose to open","body":["I wanted the transition to become part of the story. Instead of selecting a destination, the visitor holds the edge of one reality and reveals another. The next place is visible before committing to it.","The interaction gives that decision a physical form. Pinch with both hands to grip. Move them apart to open the tear. Before crossing begins, releasing both grips lets it heal; holding it open takes the visitor through. A fresh grip begins the next transition.","I placed the seam below eye level and amplified its response so the opening would ask for less reach. These were comfort-oriented design decisions, rather than evidence of a proven ergonomic benefit. Desktop controls provide another way to explore the same sequence."],"states":[{"name":"Reveal","context":"Both hands grip the seam and move apart.","response":"The opening grows and reveals the next place before the visitor commits."},{"name":"Let it heal","context":"Both grips release before crossing begins.","response":"The tear closes in the current world, leaving room to reconsider."},{"name":"Cross","context":"The visitor keeps the tear fully open.","response":"The opening expands into the next world. Releasing during this transition does not reverse it."},{"name":"Begin again","context":"The visitor has arrived in the next world.","response":"A fresh seam is available. Release the previous grip and make a new pinch to continue."}]},{"title":"Building an emotional route","body":["The route stays simple: familiar room → Ocean → Shadow → Forest → familiar room. What changes is the visitor’s relationship with being there.","These are intended emotional beats, not measured audience responses. Titles now read as the dreamer’s thoughts rather than a list of destinations."],"flow":{"label":"The dream in five moments","steps":[{"title":"Did I Wake Up?","body":"A familiar room becomes impossible when a seam opens in the air."},{"title":"How Am I Breathing?","body":"Underwater disbelief gives way to wonder and a wish to stay."},{"title":"Something Knows I’m Here","body":"A nightmare reverses that wish. The character expects to wake, but cannot."},{"title":"Is This Finally Real?","body":"A living forest offers relief without certainty."},{"title":"Did I Wake Up?","body":"The same room returns, but the tear keeps the dream unresolved."}]}},{"title":"Forest: move the attention from the backdrop to the ground","body":["When I shared the prototype with friends through a headset, their informal feedback contrasted Ocean’s detail with Forest’s less convincing sense of place. The background suggested woodland, but where they stood did not feel equally developed. Awkward deer movement also interrupted the impression of a living environment.","I began with a five-by-five-metre ground sample so I could review one area before extending the treatment. The first change was so subtle that I could not reliably tell where it was. A temporary downward arrow made the sample visible during review; it was removed after the treatment was extended.","I then refined the brief in smaller steps: denser grass, a mix of heights, fewer road-like gaps and natural ground details. Once the density improved, I challenged its artificial appearance. Later passes addressed a fresher light, animal tone and a pond that blended with its surroundings. The goal was a coherent place around the visitor, not a detailed image in the distance.","Movement exposed another constraint. As detail increased, walking, turning and entering Forest became laggy. I asked for repeated optimization while preserving the visual direction. That made performance part of the experience review, although frame-time spikes and latest headset validation remain open issues."],"comparison":{"before":"The distant woodland carried the forest identity while the near ground felt sparse or disconnected.","after":"The review moved into grass coverage, height variation, soil, light, animal movement and the pond—details at the visitor’s own scale.","note":"The earlier sample captures and current live view belong to different iterations and viewpoints; this is a progression, not a controlled visual experiment."}},{"title":"Shadow: give the fear its own place","body":["The earlier woodland direction did not separate Shadow strongly enough from Forest. I asked for a different environmental identity: lava, volcanic terrain, an oppressive red sky, nearby planets and unfamiliar creatures. This gave the unsettling part of the journey a distinct setting.","The first volcanic passes still felt assembled rather than convincing. I reviewed mountain shapes and lava paths, asking for less smooth terrain, then correcting a result that became too blocky. I also challenged lava that read as a straight line. These were small visual decisions with a larger purpose: make the elements appear to belong to the same place.","Further one-to-one reviews brought flying creatures, creature calls and a more coherent sky into the scene. I judged additions against atmosphere and usability, rather than treating a longer asset list as an improvement. Fear remained an intended experience to evaluate with people, not a result proven by adding horror objects."]},{"title":"The story changed when the narrator entered the dream","body":["I explored several researched story directions with ChatGPT. An archive concept was initially selected and developed, but hearing it in the experience made its distance from the visitor clear. I rejected that direction and the robotic delivery. Repetition and echo also pulled attention toward the narration itself.","The new premise became more immediate: I thought I had woken up, but a cut in the air led somewhere impossible. The voice was now the dreamer’s own reaction. Ocean made breathing underwater a discovery; Shadow turned the wish to stay into a need to wake; Forest allowed relief without settling whether the dream had ended.","I kept refining the performance after the words improved. I asked for fear in the voice and breathing, compared two stronger directions and selected B: trying not to be heard. Shadow and return became more strained and hushed; Ocean kept wonder and Forest relief. Pauses gave the unanswered questions space.","I also replaced destination-style labels with thoughts such as How Am I Breathing? and Is This Finally Real? Captions follow the final phrases, voice can be muted, and replay is a deliberate action. Crossing stops the previous speech so one world’s voice does not compete with the next."]},{"title":"The current outcome: one dream, five moments","body":["The live prototype now connects the opening, Ocean, Shadow, Forest and return through the same hand-opened threshold and a first-person dream. The room and worlds retain their own identities, while the voice and titles connect the emotional route.","These are live desktop captures of the current prototype. Earlier material is labeled separately."]},{"title":"What the review establishes—and what comes next","body":["The original user session and later informal friends’ feedback helped identify what to preserve and what to reconsider. My continued design reviews then shaped the ground, atmosphere, narrative and smaller interaction details. These sources have different roles; they are not one formal usability study of the latest version.","Live desktop checks completed the route through all worlds, with movement between crossings, visible dream captions and working portfolio links. They establish functional behavior in that browser run. They do not establish how frightened or delighted a new visitor feels.","First entry still has a noticeable preparation wait, and earlier desktop checks recorded frame-time spikes. The latest Quest 3S version needs a physical-device session for text legibility while moving, voice clarity, tracking interruptions, comfort and sustained performance. The next test should also ask whether people understand how to begin and recover, and whether the return creates curiosity rather than confusion."]},{"title":"What this project taught me about directing AI","body":["The most useful part of working with ChatGPT was the conversation around a result. A broad request for immersion became more actionable when I could name the disconnected ground, the straight lava, the artificial grass or the voice explaining too much. Better distinctions produced a clearer next iteration.","I learned to keep reviewing the relationship between elements. More detail could introduce lag; a rougher mountain could look blocky; more dramatic sound could distract from the person speaking. My role was to decide what the experience needed, challenge an output and keep the revisions consistent with that intention."]},{"title":"Making the experience work","body":["The prototype uses Three.js and WebXR for desktop and Meta Quest 3S. Selected external models, textures, panoramas and sound work alongside procedural environments. ChatGPT assisted logic development, implementation and checks under my creative direction.","Dream narration uses locally generated prerecorded Qwen3-TTS audio with timed captions. The voice model does not run during the experience. Source and licence records remain with the standalone project; its original creators retain credit."]}]}]};
